const PEDIDO_HEADERS = PEDIDO_ATTR_HEADERS;
const ensureFormularioHeaders = (snapshot) => {
  const sheet = findSheet(snapshot, /formulario|aprobaci/i);
  if (!sheet) return snapshot;
  for (const [col, label] of Object.entries(FORMULARIO_HEADERS)) {
    setHeaderIfNeeded(sheet, `${col}1`, label);
  }
  return snapshot;
};


/**
 * sync_order_draft_from_odoo — Kapso ← Odoo (fuente de verdad).
 * Reconstruye resolved_lines + people desde sale.order + spreadsheet.
 */
async function odooRpc(env, service, method, args) {
  const resp = await fetch(`${env.ODOO_URL}/jsonrpc`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      jsonrpc: "2.0",
      method: "call",
      params: { service, method, args },
    }),
  });
  const json = await resp.json();
  if (json?.error) throw new Error(json.error?.message || "Odoo RPC error");
  return json.result;
}

function decodeSnapshot(b64) {
  if (!b64 || b64 === false) return null;
  try {
    const binary = atob(String(b64));
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return JSON.parse(new TextDecoder().decode(bytes));
  } catch {
    try {
      // Node fallback
      const raw = Buffer.from(b64, "base64").toString("utf8");
      return JSON.parse(raw);
    } catch {
      return null;
    }
  }
}

async function syncOrderDraftFromOdoo(env, { orderId, orderName } = {}) {
  if (!env?.ODOO_URL || !env?.ODOO_DB || !env?.ODOO_USERNAME || !env?.ODOO_PASSWORD) {
    return { ok: false, error: "odoo_unavailable" };
  }
  const uid = await odooRpc(env, "common", "authenticate", [
    env.ODOO_DB,
    env.ODOO_USERNAME,
    env.ODOO_PASSWORD,
    {},
  ]);
  if (!uid) return { ok: false, error: "auth_failed" };

  const executeKw = (model, method, positionalArgs = [], kw = {}) =>
    odooRpc(env, "object", "execute_kw", [
      env.ODOO_DB,
      uid,
      env.ODOO_PASSWORD,
      model,
      method,
      positionalArgs,
      kw,
    ]);

  let soId = Number(orderId || 0) || null;
  if (!soId && orderName) {
    const found = await executeKw(
      "sale.order",
      "search_read",
      [[["name", "ilike", String(orderName).replace(/^S0*/i, "")]]],
      { fields: ["id", "name"], limit: 5 }
    );
    const exact = (found || []).find(
      (o) => String(o.name).toUpperCase() === String(orderName).toUpperCase()
    );
    soId = exact?.id || found?.[0]?.id || null;
  }
  if (!soId) return { ok: false, error: "order_not_found" };

  const orders = await executeKw(
    "sale.order",
    "read",
    [[soId]],
    {
      fields: [
        "id",
        "name",
        "state",
        "note",
        "partner_id",
        "order_line",
        "client_order_ref",
        "spreadsheet_ids",
      ],
    }
  );
  const order = orders?.[0];
  if (!order) return { ok: false, error: "order_not_found" };

  const lines = await executeKw(
    "sale.order.line",
    "search_read",
    [[["order_id", "=", soId], ["display_type", "=", false]]],
    {
      fields: [
        "id",
        "name",
        "product_id",
        "product_uom_qty",
        "price_unit",
        "product_template_id",
      ],
    }
  );

  const resolved_lines = [];
  for (let i = 0; i < (lines || []).length; i++) {
    const line = lines[i];
    const productId = line.product_id?.[0];
    if (!productId) continue;
    if (/dise[nñ]o/i.test(line.name || line.product_id?.[1] || "")) continue;

    let ptavs = [];
    const products = await executeKw(
      "product.product",
      "read",
      [[productId]],
      {
        fields: [
          "id",
          "display_name",
          "product_tmpl_id",
          "product_template_attribute_value_ids",
          "list_price",
        ],
      }
    );
    const product = products?.[0];
    if (product?.product_template_attribute_value_ids?.length) {
      ptavs = await executeKw(
        "product.template.attribute.value",
        "read",
        [product.product_template_attribute_value_ids],
        { fields: ["id", "name", "attribute_id"] }
      );
    }
    const split = splitProductDisplayName(product?.display_name || line.name);
    resolved_lines.push(
      buildResolvedLine(
        {
          line_id: `odoo_line_${line.id}`,
          product_text: product?.display_name || line.name,
          product_base: split.product_base,
          product_tmpl_id: product?.product_tmpl_id?.[0] || line.product_template_id?.[0],
          product_variant_id: productId,
          quantity: line.product_uom_qty,
          unit_cop: line.price_unit,
          confidence: "high",
          attributes: {
            ...split.embedded_attrs,
            ...attributesFromOdooPtavs(ptavs),
          },
        },
        i
      )
    );
  }

  let spreadsheetId = null;
  let spreadsheetUrl = null;
  let people = [];
  let pedidoAttrs = [];
  const sheetIds = order.spreadsheet_ids || [];
  if (sheetIds.length) {
    spreadsheetId = sheetIds[sheetIds.length - 1];
    const sheets = await executeKw(
      "sale.order.spreadsheet",
      "read",
      [[spreadsheetId]],
      { fields: ["id", "name", "spreadsheet_snapshot", "order_id"] }
    );
    const sheet = sheets?.[0];
    const snap = decodeSnapshot(sheet?.spreadsheet_snapshot);
    if (snap) {
      people = parsePeopleFromSpreadsheet(snap);
      pedidoAttrs = parsePedidoAttributes(snap);
      // merge pedido attrs into resolved lines by index
      pedidoAttrs.forEach((pa, idx) => {
        if (resolved_lines[idx]) {
          resolved_lines[idx].attributes = {
            ...resolved_lines[idx].attributes,
            ...pa.attributes,
          };
          if (pa.comments) resolved_lines[idx].comments = pa.comments;
          if (pa.product_base) resolved_lines[idx].product_base = pa.product_base;
        }
      });
    }
    spreadsheetUrl = `${env.ODOO_URL}/odoo/sales/${soId}/sale-order-spreadsheet/${spreadsheetId}`;
  }

  const detail = {
    schema_version: "life_order_people_v1",
    source: "odoo_sync",
    parse_status: "ok",
    people,
    person_count: people.length,
    rows: people.map((p) => ({
      nombre: p.identity?.print_name || "",
      numero: p.identity?.number || "",
      talla: p.components?.[0]?.size || "",
      comentario: p.comments || "",
      resolved_line_id: p.resolved_line_id || "",
    })),
  };

  return {
    ok: true,
    order: {
      id: order.id,
      name: order.name,
      state: order.state,
      partner_id: order.partner_id,
    },
    order_draft: {
      detail,
      commercial: {
        lines: resolved_lines.map((l) => ({
          product_text: l.product_text,
          quantity: l.quantity,
          category: l.category,
        })),
        resolved_lines,
      },
      spreadsheet: {
        id: spreadsheetId,
        url: spreadsheetUrl,
        status: people.length ? "complete" : "partial",
        source_of_truth: "odoo",
      },
      write: {
        status: "ready",
        code: "synced_from_odoo",
        synced_at: new Date().toISOString(),
      },
    },
  };
}



/**
 * Búsqueda y corrección de pedidos staff (sale.order + project.task).
 * Editable mientras la tarjeta NO esté en impresión / fabricación.
 */

/** Etapas donde ya no se puede corregir lista sin costo */
const LOCKED_STAGE_RE =
  /a\s*imprimir|fabricaci[oó]n|sublimaci[oó]n|confecci[oó]n|\bcorte\b|cobro\s*y\s*entrega|\bhecho\b|cancelad|entregad/i;

const EXCEL_VERIFY_WARNING =
  "Revise bien el Excel o la lista antes de confirmar: una vez el pedido pase a impresión o fabricación, los cambios del cliente tienen costo adicional.";

function hasOdooCredentials(env = {}) {
  return Boolean(env.ODOO_URL && env.ODOO_DB && env.ODOO_USERNAME && env.ODOO_PASSWORD);
}

function odooCredentialsError(toolName) {
  return {
    ok: false,
    error: "odoo_unavailable",
    message: `No hay credenciales Odoo en la función ${toolName}.`,
  };
}

/** Número corto del pedido: 2564 desde "2564", "02564", "S02564" */
function bareOrderNumber(raw) {
  let s = String(raw || "").trim().toUpperCase();
  s = s.replace(/^S0*/i, "").replace(/^S/i, "");
  const digits = s.replace(/\D/g, "");
  if (!digits) return null;
  return String(parseInt(digits, 10));
}

function bareOrderNumberFromName(orderName) {
  const m = String(orderName || "").match(/S0*(\d+)/i);
  return m ? String(parseInt(m[1], 10)) : null;
}

function parseDetailRowsFromNoteHtml(html) {
  const rows = [];
  const body = String(html || "");
  const tbodyMatch = body.match(/<tbody>([\s\S]*?)<\/tbody>/i);
  if (!tbodyMatch) return rows;
  const trs = tbodyMatch[1].match(/<tr[^>]*>[\s\S]*?<\/tr>/gi) || [];
  for (const tr of trs) {
    const tds = [...tr.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map((m) =>
      m[1]
        .replace(/<[^>]+>/g, "")
        .replace(/&amp;/g, "&")
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
        .trim()
    );
    if (tds.length < 2) continue;
    const nombre = tds[1];
    if (!nombre || /^nombre$/i.test(nombre)) continue;
    rows.push({
      numero: tds[0] === "—" ? "" : tds[0],
      nombre,
      talla: tds[2] === "—" ? "" : tds[2] || "",
      rol: tds[3] || "",
      manga: "",
      grupo: "",
    });
  }
  return rows.map((r) => toDetailRow(r)).filter(Boolean);
}

function patchDetailRows(existing, changes) {
  const out = (existing || []).map((r) => ({ ...r }));
  for (const raw of changes || []) {
    const ch = toDetailRow(raw);
    if (!ch) continue;
    const idx = out.findIndex(
      (r) =>
        (ch.numero && r.numero === ch.numero) ||
        (ch.nombre && r.nombre.toLowerCase() === ch.nombre.toLowerCase())
    );
    if (idx >= 0) out[idx] = { ...out[idx], ...ch };
    else out.push(ch);
  }
  return out;
}

function rowProductBucket(row) {
  const r = toDetailRow(row);
  if (!r) return "campo";
  if (r.arquero || /arquer|porter/i.test(r.rol || "")) return "arquero";
  const m = `${r.manga || ""} ${r.rol || ""}`.toLowerCase();
  if (/manga\s*larg|larg[ao]/.test(m)) return "manga_larga";
  if (/manga\s*cort|cort[ao]|sisa/.test(m)) return "manga_corta";
  return "campo";
}

function countRowsByBucket(rows) {
  const counts = { campo: 0, arquero: 0, manga_larga: 0, manga_corta: 0 };
  for (const row of rows || []) {
    const bucket = rowProductBucket(row);
    counts[bucket] = (counts[bucket] || 0) + 1;
  }
  return counts;
}

function detectProductMixChanges(oldRows, newRows) {
  return JSON.stringify(countRowsByBucket(oldRows)) !== JSON.stringify(countRowsByBucket(newRows));
}

function summarizeListDiff(oldRows, newRows) {
  const old = (oldRows || []).map((r) => toDetailRow(r)).filter(Boolean);
  const neu = (newRows || []).map((r) => toDetailRow(r)).filter(Boolean);
  const parts = [];
  if (detectProductMixChanges(old, neu)) {
    const ob = countRowsByBucket(old);
    const nb = countRowsByBucket(neu);
    const deltas = [];
    for (const key of Object.keys(nb)) {
      const d = (nb[key] || 0) - (ob[key] || 0);
      if (d) deltas.push(`${key.replace(/_/g, " ")} ${d > 0 ? "+" : ""}${d}`);
    }
    parts.push(`Variantes: ${deltas.join(", ") || "mezcla distinta"}`);
  }
  let detailChanges = 0;
  for (const nr of neu) {
    const match = old.find((o) => o.nombre.toLowerCase() === nr.nombre.toLowerCase());
    if (!match) {
      detailChanges++;
      continue;
    }
    if (match.talla !== nr.talla || match.numero !== nr.numero) detailChanges++;
  }
  if (detailChanges) parts.push(`${detailChanges} fila(s) con talla/número/nombre`);
  return parts.join(" · ") || "Lista actualizada";
}

function extractTitleFromNoteHtml(html) {
  const m = String(html || "").match(/<h1>([\s\S]*?)<\/h1>/i);
  return m ? m[1].replace(/<[^>]+>/g, "").trim() : "";
}

function extractCommercialSummaryFromNoteHtml(html) {
  const m = String(html || "").match(
    /<h2>Resumen de uniformes<\/h2>[\s\S]*?(?=\n\n<hr>|\n\n<h2>|$)/i
  );
  return m ? m[0].trim() : "";
}

function mangaQtyParts(r) {
  if (Array.isArray(r.manga_parts) && r.manga_parts.length) {
    return r.manga_parts.map((p) => ({
      manga: String(p.manga || "").toLowerCase(),
      qty: Math.max(1, Number(p.qty) || 1),
    }));
  }
  const qty = Math.max(1, Number(r.cantidad || 1) || 1);
  const m = String(r.manga || "").toLowerCase();
  const hasL = /larga/.test(m);
  const hasC = /corta|sisa/.test(m);
  if (hasL && hasC) {
    // Sin desglose numérico: no inventar split; contar qty completa en el primer tipo
    return [{ manga: "larga", qty }];
  }
  if (hasL) return [{ manga: "larga", qty }];
  if (hasC) return [{ manga: "corta", qty }];
  return [{ manga: "corta", qty }];
}

function countRowsBySoLineBucket(rows) {
  const counts = {
    uniforme_corta: 0,
    uniforme_larga: 0,
    camiseta_corta: 0,
    camiseta_larga: 0,
  };
  for (const row of rows || []) {
    const r = toDetailRow(row);
    if (!r) continue;
    if (r.pantaloneta) continue;
    const isArquero = r.arquero || /arquer|porter/i.test(r.rol || "");
    const parts = mangaQtyParts(r);
    const add = (bucket, q) => {
      counts[bucket] += q;
    };
    for (const part of parts) {
      const q = part.qty;
      const isLarga = part.manga === "larga";
      if (r.camiseta && r.grupo === "femenino") {
        add(isLarga ? "camiseta_larga" : "camiseta_corta", q);
        continue;
      }
      if (isArquero) {
        if (r.grupo === "masculino" && r.uniforme !== false && !r.camiseta) {
          add(isLarga ? "uniforme_larga" : "uniforme_corta", q);
        } else {
          add(isLarga ? "camiseta_larga" : "camiseta_corta", q);
        }
        continue;
      }
      if (r.camiseta) {
        add(isLarga ? "camiseta_larga" : "camiseta_corta", q);
      } else {
        add(isLarga ? "uniforme_larga" : "uniforme_corta", q);
      }
    }
  }
  return counts;
}

function lineBucketFromSoName(name) {
  const n = String(name || "").toLowerCase();
  if (/diseño|diseno/.test(n)) return "design";
  const isCamiseta = /camiseta/.test(n) && !/uniforme/.test(n);
  const isLarga = /manga\s*larg|\blarga\b/.test(n);
  if (isCamiseta) return isLarga ? "camiseta_larga" : "camiseta_corta";
  if (/uniforme/.test(n)) return isLarga ? "uniforme_larga" : "uniforme_corta";
  if (/manga\s*cort|cort[ao]|sisa/.test(n)) return "uniforme_corta";
  return "campo";
}

async function syncSoLinesFromProductMix(executeKw, orderId, newRows, productIdByBucket = {}) {
  const buckets = { ...countRowsBySoLineBucket(newRows) };
  const lines = await executeKw(
    "sale.order.line",
    "search_read",
    [[["order_id", "=", orderId]]],
    { fields: ["id", "name", "product_uom_qty", "product_id"] }
  );
  const updates = [];
  const unmatched = [];

  for (const line of lines || []) {
    const bucket = lineBucketFromSoName(line.name);
    if (bucket === "design") continue;
    const targetQty = buckets[bucket] || 0;
    const currentQty = Number(line.product_uom_qty || 0);
    if (targetQty > 0) {
      if (currentQty !== targetQty) {
        await executeKw("sale.order.line", "write", [[line.id], { product_uom_qty: targetQty }]);
        updates.push({ line_id: line.id, name: line.name, from: currentQty, to: targetQty });
      } else {
        updates.push({ line_id: line.id, name: line.name, matched: true, qty: currentQty });
      }
      buckets[bucket] = 0;
    } else if (currentQty > 0 && bucket !== "campo" && bucket !== "design") {
      await executeKw("sale.order.line", "write", [[line.id], { product_uom_qty: 0 }]);
      updates.push({ line_id: line.id, name: line.name, from: currentQty, to: 0 });
    }
  }

  for (const [bucket, qty] of Object.entries(buckets)) {
    if (qty <= 0) continue;
    const productId = productIdByBucket[bucket];
    if (!productId) {
      unmatched.push({ bucket, qty });
      continue;
    }
    const newLineId = await executeKw("sale.order.line", "create", [
      {
        order_id: orderId,
        product_id: productId,
        product_uom_qty: qty,
      },
    ]);
    updates.push({ created: true, bucket, product_id: productId, qty, line_id: newLineId });
  }

  return { updates, unmatched, expected: countRowsBySoLineBucket(newRows) };
}

function normalizeStageName(stageName) {
  return String(stageName || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function isStageEditable(stageName) {
  const s = normalizeStageName(stageName);
  if (!s) return true;
  return !LOCKED_STAGE_RE.test(s);
}

function changeTypeLabel(changeType) {
  const map = {
    cliente: "Cambio solicitado por el cliente",
    error_interno: "Corrección error interno Life (sin costo al cliente)",
    error_diseno: "Corrección error de diseño Life (sin costo al cliente)",
  };
  return map[changeType] || "Corrección de pedido";
}

function buildCorrectionChatterHtml({
  changeType,
  changeSummary,
  staffLabel,
  orderName,
  rowCount,
  productMixChanged,
  revisionNumber,
}) {
  const label = changeTypeLabel(changeType);
  const who = staffLabel || "Staff WhatsApp";
  const summary = String(changeSummary || "").trim() || "Actualización de lista.";
  const rows = rowCount ? `<p>Filas: <strong>${rowCount}</strong>.</p>` : "";
  const soNote = productMixChanged
    ? "<p>SO actualizada (cambió variante/producto).</p>"
    : "<p>SO sin cambios (solo lista en tarea).</p>";
  const revision = revisionNumber
    ? `<p>Revisión estructurada: <strong>V${String(revisionNumber).padStart(4, "0")}</strong>.</p>`
    : "";

  return `<p><strong>${label}</strong> — ${orderName || ""}</p>
<p>${who}</p>
<p>${summary}</p>
${rows}
${soNote}
${revision}`;
}

function jsonToBase64(value) {
  const bytes = new TextEncoder().encode(JSON.stringify(value, null, 2));
  let binary = "";
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunk));
  }
  return btoa(binary);
}

async function archiveOrderRevision(executeKw, {
  order,
  task,
  beforeLines,
  changeType,
  changeSummary,
  staffLabel,
  listMode,
  productMixChanged,
  rowCount,
}) {
  const existing = await executeKw(
    "ir.attachment",
    "search_read",
    [[
      ["res_model", "=", "sale.order"],
      ["res_id", "=", order.id],
      ["name", "ilike", "life-order-revision-v"],
    ]],
    { fields: ["id", "name"], limit: 200, order: "id asc" }
  );
  const maxRevision = (existing || []).reduce((max, attachment) => {
    const match = String(attachment.name || "").match(/revision-v(\d+)/i);
    return Math.max(max, match ? Number(match[1]) : 0);
  }, 0);
  const number = maxRevision + 1;
  const ordersAfter = await executeKw("sale.order", "read", [[order.id]], {
    fields: ["id", "name", "state", "note", "amount_total", "write_date"],
  });
  const orderAfter = Array.isArray(ordersAfter) ? ordersAfter[0] : {};
  const tasksAfter = task?.id
    ? await executeKw("project.task", "read", [[task.id]], {
        fields: ["id", "name", "stage_id", "description", "write_date"],
      })
    : [];
  const taskAfter = Array.isArray(tasksAfter) ? tasksAfter[0] : null;
  const linesAfter = await executeKw(
    "sale.order.line",
    "search_read",
    [[["order_id", "=", order.id]]],
    {
      fields: ["id", "product_id", "name", "product_uom_qty", "price_unit", "write_date"],
      limit: 200,
      order: "id asc",
    }
  );
  const createdAt = new Date().toISOString();
  const snapshot = {
    schema_version: "life_order_revision_v1",
    revision_number: number,
    created_at: createdAt,
    order_id: order.id,
    order_name: order.name,
    order_state: order.state,
    change: {
      type: changeType,
      summary: changeSummary,
      requested_by: staffLabel,
      list_mode: listMode,
      product_mix_changed: Boolean(productMixChanged),
      row_count: Number(rowCount || 0),
    },
    before: {
      order: {
        note: order.note || "",
        amount_total: Number(order.amount_total || 0),
        write_date: order.write_date || null,
      },
      task: task
        ? {
            id: task.id,
            stage_id: task.stage_id || null,
            description: task.description || "",
            write_date: task.write_date || null,
          }
        : null,
      lines: beforeLines || [],
    },
    after: {
      order: orderAfter,
      task: taskAfter,
      lines: linesAfter || [],
    },
  };
  const name = `life-order-revision-v${String(number).padStart(4, "0")}.json`;
  const attachmentId = await executeKw("ir.attachment", "create", [
    {
      name,
      res_model: "sale.order",
      res_id: order.id,
      type: "binary",
      mimetype: "application/json",
      raw: jsonToBase64(snapshot),
    },
  ]);
  return { number, name, attachment_id: attachmentId, created_at: createdAt };
}

async function createOdooClient(env) {
  const rpc = async (service, method, args) => {
    const resp = await fetch(`${env.ODOO_URL}/jsonrpc`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: { service, method, args } }),
    });
    const json = await resp.json();
    if (json?.error) throw new Error(json.error?.message || "Odoo RPC error");
    return json.result;
  };
  const uid = await rpc("common", "authenticate", [
    env.ODOO_DB,
    env.ODOO_USERNAME,
    env.ODOO_PASSWORD,
    {},
  ]);
  if (!uid) throw new Error("Odoo authentication failed");
  const executeKw = (model, method, positionalArgs = [], kw = {}) =>
    rpc("object", "execute_kw", [
      env.ODOO_DB,
      uid,
      env.ODOO_PASSWORD,
      model,
      method,
      positionalArgs,
      kw,
    ]);
  return { uid, executeKw };
}

function mapOrderRow(order, task) {
  const stage = Array.isArray(task?.stage_id) ? task.stage_id[1] : null;
  const editable = isStageEditable(stage);
  return {
    order_id: order.id,
    order_name: order.name,
    order_state: order.state,
    partner_name: Array.isArray(order.partner_id) ? order.partner_id[1] : null,
    partner_id: Array.isArray(order.partner_id) ? order.partner_id[0] : order.partner_id,
    amount_total: Number(order.amount_total || 0),
    date_order: order.date_order || null,
    task_id: task?.id || null,
    task_name: task?.name || null,
    task_stage: stage,
    editable,
    lock_reason: editable
      ? null
      : `Etapa «${stage}»: el pedido ya está en impresión o fabricación. Los cambios del cliente tienen costo.`,
  };
}

async function loadOrderBundle(executeKw, orderId) {
  const orders = await executeKw("sale.order", "read", [[orderId]], {
    fields: ["id", "name", "state", "partner_id", "amount_total", "date_order", "note", "write_date"],
  });
  const order = Array.isArray(orders) ? orders[0] : null;
  if (!order?.id) return null;

  const tasks = await executeKw(
    "project.task",
    "search_read",
    [[["sale_order_id", "=", orderId]]],
    {
      fields: ["id", "name", "stage_id", "description", "write_date"],
      limit: 1,
      order: "id desc",
    }
  );
  const task = Array.isArray(tasks) ? tasks[0] : null;
  return { order, task, mapped: mapOrderRow(order, task) };
}

/** Texto plano de un mensaje WhatsApp (Kapso / Cloud API). */
function waMessageText(msg) {
  if (!msg || typeof msg !== "object") return "";
  const direct = msg.content ?? msg.body;
  if (typeof direct === "string" && direct.trim()) return direct.trim();
  const nested = msg.text;
  if (typeof nested === "string" && nested.trim()) return nested.trim();
  if (nested && typeof nested === "object") {
    const body = nested.body ?? nested.text;
    if (typeof body === "string" && body.trim()) return body.trim();
  }
  if (typeof msg.caption === "string" && msg.caption.trim()) return msg.caption.trim();
  return "";
}

function extractOrderNumberFromText(text) {
  const s = String(text || "");
  const soMatch = s.match(/\bS0*(\d{3,6})\b/i);
  if (soMatch) return bareOrderNumber(soMatch[0]);
  const pedidoMatch = s.match(/(?:pedido|orden|presupuesto|so|n[°º]?)\s*#?\s*0*(\d{3,6})\b/i);
  if (pedidoMatch) return bareOrderNumber(pedidoMatch[1]);
  const corrMatch = s.match(/(?:corregir|actualizar|modificar|update)\s+(?:el\s+)?(?:pedido\s+)?#?\s*0*(\d{3,6})\b/i);
  if (corrMatch) return bareOrderNumber(corrMatch[1]);
  const looseNum = s.match(/\b0*(\d{4,6})\b/);
  if (looseNum && /actualizar|corregir|modificar|pedido|lista/i.test(s)) {
    return bareOrderNumber(looseNum[1]);
  }
  return null;
}

function extractCustomerNameFromText(text) {
  const s = String(text || "").trim();
  if (!s) return null;
  const afterNum = s.match(/\b0*\d{3,6}\b\s+([A-Za-zÁÉÍÓÚáéíóúñÑ][\w\sÁÉÍÓÚáéíóúñÑ.-]{2,40})/);
  if (afterNum) return afterNum[1].trim();
  const deMatch = s.match(/(?:de|para|cliente)\s+([A-Za-zÁÉÍÓÚáéíóúñÑ][\w\sÁÉÍÓÚáéíóúñÑ.-]{2,40})/i);
  if (deMatch) return deMatch[1].trim();
  return null;
}

/** Une input explícito + vars persistidas + texto reciente del hilo WhatsApp. */
function resolveStaffOrderSearchInput(body = {}) {
  const input = body?.input || {};
  const vars = body?.execution_context?.vars || {};
  const messages = Array.isArray(body?.whatsapp_context?.messages)
    ? body.whatsapp_context.messages
    : [];

  const fromInput = bareOrderNumber(
    input.order_number || input.order_name || input.numero_pedido || ""
  );

  if (vars.order_correction?.target_order_id) {
    const n =
      fromInput ||
      bareOrderNumber(vars.order_correction.target_order_name || "") ||
      bareOrderNumber(vars.order?.name || "");
    return {
      order_number: n,
      order_id: vars.order_correction.target_order_id,
      customer_phone: input.customer_phone || input.phone || "",
      customer_name: input.customer_name || "",
      source: fromInput ? "input" : "vars.order_correction",
      already_resolved: true,
    };
  }

  if (vars.order?.id) {
    const n = fromInput || bareOrderNumber(vars.order.name || "");
    if (n) {
      return {
        order_number: n,
        order_id: vars.order.id,
        customer_phone: input.customer_phone || input.phone || "",
        customer_name: input.customer_name || "",
        source: fromInput ? "input" : "vars.order",
        already_resolved: true,
      };
    }
  }

  let orderNumber = fromInput;
  let source = orderNumber ? "input" : null;

  if (!orderNumber) {
    orderNumber = bareOrderNumber(vars.order_correction?.target_order_name || "");
    if (orderNumber) source = "vars.order_correction";
  }

  let customerName = String(input.customer_name || input.partner_name || "").trim();

  if (!orderNumber || !customerName) {
    for (const msg of [...messages].reverse()) {
      if (msg.direction && msg.direction !== "inbound") continue;
      const text = waMessageText(msg);
      if (!text) continue;
      if (!orderNumber) {
        const found = extractOrderNumberFromText(text);
        if (found) {
          orderNumber = found;
          source = "whatsapp_thread";
        }
      }
      if (!customerName) {
        const name = extractCustomerNameFromText(text);
        if (name) customerName = name;
      }
      if (orderNumber && customerName) break;
    }
  }

  return {
    order_number: orderNumber,
    order_id: null,
    customer_phone: input.customer_phone || input.phone || "",
    customer_name: customerName,
    source,
    already_resolved: false,
  };
}

function orderNameCandidates(bareNumber) {
  const n = parseInt(String(bareNumber || ""), 10);
  if (!n) return [];
  return [...new Set([`S0${String(n).padStart(4, "0")}`, `S0${n}`, `S${n}`])];
}

/** Dominio Odoo OR en notación polaca: ['|', '|', A, B, C] */
function odooOrDomain(conditions) {
  const items = (conditions || []).filter(Boolean);
  if (!items.length) return [];
  if (items.length === 1) return items;
  return [...Array(items.length - 1).fill("|"), ...items];
}

async function searchStaffOrders(executeKw, input = {}) {
  const orderNumber = bareOrderNumber(
    input.order_number || input.order_name || input.numero_pedido || ""
  );
  const customerPhone = String(input.customer_phone || input.phone || "").trim();
  const customerName = String(input.customer_name || input.partner_name || "").trim();
  const limit = Math.min(Math.max(Number(input.limit || 5), 1), 10);

  const orderFields = ["id", "name", "state", "partner_id", "amount_total", "date_order", "write_date"];

  if (!orderNumber) {
    return {
      orders: [],
      partner_id: null,
      note: "Indique el número del pedido (solo dígitos, ej. 2564).",
      order_number: null,
    };
  }

  const nameCandidates = orderNameCandidates(orderNumber);
  const nameOr = odooOrDomain(nameCandidates.map((name) => ["name", "ilike", name]));

  let domain = ["&", ["state", "in", ["draft", "sent", "sale"]], ...nameOr];

  let resolvedPartnerId = 0;
  if (customerPhone) {
    const lookup = await findPartnerByWaPhone(executeKw, customerPhone, {
      fields: ["id", "name"],
    });
    resolvedPartnerId = lookup.partner?.id || 0;
    if (resolvedPartnerId) {
      domain = ["&", ["partner_id", "=", resolvedPartnerId], ...domain];
    }
  } else if (customerName) {
    domain = ["&", ["partner_id.name", "ilike", customerName], ...domain];
  }

  const rows = await executeKw("sale.order", "search_read", [domain], {
    fields: orderFields,
    limit: 20,
    order: "id desc",
  });

  let matched = (rows || []).filter(
    (o) => bareOrderNumberFromName(o.name) === orderNumber
  );

  if (!matched.length) {
    matched = await searchStaffOrdersViaTask(executeKw, orderNumber, customerName, orderFields);
  }

  return {
    orders: await enrichOrdersWithTasks(executeKw, matched.slice(0, limit)),
    partner_id:
      (Array.isArray(matched[0]?.partner_id) ? matched[0].partner_id[0] : null) ||
      resolvedPartnerId ||
      null,
    note: matched.length ? null : `No encontré pedido ${orderNumber}${customerName ? ` (${customerName})` : ""}.`,
    order_number: orderNumber,
  };
}

async function searchStaffOrdersViaTask(executeKw, orderNumber, customerName, orderFields) {
  const nameCandidates = orderNameCandidates(orderNumber);
  const taskNameConds = [
    ...nameCandidates.map((name) => ["name", "ilike", name]),
    ["name", "ilike", orderNumber],
  ];
  let taskDomain = odooOrDomain(taskNameConds);
  if (customerName) {
    taskDomain = ["&", ["partner_id.name", "ilike", customerName], ...taskDomain];
  }

  const tasks = await executeKw("project.task", "search_read", [taskDomain], {
    fields: ["id", "name", "stage_id", "sale_order_id", "partner_id"],
    limit: 10,
    order: "id desc",
  });

  const orderIds = [];
  const seen = new Set();
  for (const task of tasks || []) {
    const soId = Array.isArray(task.sale_order_id) ? task.sale_order_id[0] : task.sale_order_id;
    const soName = Array.isArray(task.sale_order_id) ? task.sale_order_id[1] : "";
    const taskName = String(task.name || "");
    const numOk =
      bareOrderNumberFromName(soName) === orderNumber ||
      bareOrderNumberFromName(taskName) === orderNumber ||
      taskName.includes(orderNumber);
    if (!soId || !numOk || seen.has(soId)) continue;
    seen.add(soId);
    orderIds.push(soId);
  }

  if (!orderIds.length) return [];

  const orders = await executeKw("sale.order", "read", [orderIds], { fields: orderFields });
  return (orders || []).filter((o) => bareOrderNumberFromName(o.name) === orderNumber);
}

async function enrichOrdersWithTasks(executeKw, orders) {
  const out = [];
  for (const order of orders) {
    const tasks = await executeKw(
      "project.task",
      "search_read",
      [[["sale_order_id", "=", order.id]]],
      { fields: ["id", "name", "stage_id"], limit: 1, order: "id desc" }
    );
    const task = Array.isArray(tasks) ? tasks[0] : null;
    out.push(mapOrderRow(order, task));
  }
  return out;
}

function resolveCorrectionNoteHtml(vars = {}, input = {}, options = {}) {
  const orderDraft = vars.order_draft || {};
  let detailRows = orderDraft.detail?.rows || input.detail_rows || [];
  const listMode = options.listMode || input.list_mode || "full";
  const existingHtml = options.existingNoteHtml || "";
  const productMixChanged = Boolean(options.productMixChanged);

  if (listMode === "patch" && detailRows.length && existingHtml) {
    const existingRows = parseDetailRowsFromNoteHtml(existingHtml);
    detailRows = patchDetailRows(existingRows, detailRows);
  }

  if (!detailRows.length) return null;

  const preservedCommercial = extractCommercialSummaryFromNoteHtml(existingHtml);
  const preservedTitle = extractTitleFromNoteHtml(existingHtml);

  const commercialLines =
    productMixChanged && orderDraft.commercial?.lines?.length
      ? orderDraft.commercial.lines
      : productMixChanged && vars.quote?.product_text
        ? [
            {
              name: vars.quote.product_text,
              quantity: vars.quote.quantity,
              variant_notes: orderDraft.commercial?.variant_notes || "",
            },
          ]
        : [];

  return {
    html: buildOdooOrderNoteHtml({
      title:
        preservedTitle ||
        orderDraft.title ||
        vars.quote?.order_or_team_name_for_billing ||
        "Pedido",
      commercialSummaryHtml:
        productMixChanged && commercialLines.length ? "" : preservedCommercial,
      commercialLines: productMixChanged && commercialLines.length ? commercialLines : [],
      detailRows,
      listLayout: orderDraft.detail?.excel_layout || orderDraft.detail?.layout || null,
      projectName: orderDraft.project?.name || null,
      blockers: productMixChanged ? orderDraft.blockers || [] : [],
      referenceFiles: (orderDraft.attachments || [])
        .filter((a) => a.role === "design_reference")
        .map((a) => a.filename || a.url),
      designNotes: orderDraft.design_notes || null,
    }),
    rowCount: detailRows.length,
    productMixChanged,
  };
}

async function applyOrderCorrection(executeKw, {
  orderId,
  orderNoteHtml,
  changeType,
  changeSummary,
  staffLabel,
  attachments,
  rowCount,
  listMode,
  attachmentsOnly,
  productMixChanged,
  newRows,
}) {
  const bundle = await loadOrderBundle(executeKw, orderId);
  if (!bundle) throw new Error("order_not_found");

  const { order, task, mapped } = bundle;
  if (!mapped.editable) {
    return {
      ok: false,
      error: "order_locked",
      message: mapped.lock_reason,
      order: mapped,
    };
  }

  const hasList = orderNoteHtml && orderNoteHtml.length >= 40;
  const hasAttachments = Array.isArray(attachments) && attachments.length > 0;
  const beforeLines = await executeKw(
    "sale.order.line",
    "search_read",
    [[["order_id", "=", order.id]]],
    {
      fields: ["id", "product_id", "name", "product_uom_qty", "price_unit", "write_date"],
      limit: 200,
      order: "id asc",
    }
  );

  if (!hasList && !attachmentsOnly) {
    return {
      ok: false,
      error: "missing_list",
      message: "Falta lista parseada o adjuntos.",
      order: mapped,
    };
  }

  if (hasList && task?.id) {
    await executeKw("project.task", "write", [[task.id], { description: orderNoteHtml }]);
  }

  // Presupuesto SO: siempre refrescar nota si hay lista (no solo cuando cambia el mix).
  let soLineUpdates = { updates: [], unmatched: [] };
  if (hasList) {
    await executeKw("sale.order", "write", [[order.id], { note: orderNoteHtml }]);
    if (productMixChanged) {
      soLineUpdates = await syncSoLinesFromProductMix(executeKw, order.id, newRows || []);
    }
  }

  const revision = await archiveOrderRevision(executeKw, {
    order,
    task,
    beforeLines,
    changeType,
    changeSummary,
    staffLabel,
    listMode: listMode || (hasList ? "full" : "attachments_only"),
    rowCount: hasList ? rowCount || 0 : 0,
    productMixChanged,
  });
  const chatterBody = buildCorrectionChatterHtml({
    changeType,
    changeSummary,
    staffLabel,
    orderName: order.name,
    rowCount: hasList ? rowCount || 0 : 0,
    productMixChanged,
    revisionNumber: revision.number,
  });

  try {
    await executeKw(
      "sale.order",
      "message_post",
      [[order.id]],
      {
        body: chatterBody,
        message_type: "comment",
        subtype_xmlid: "mail.mt_note",
      }
    );
  } catch (_e) {
    await executeKw("sale.order", "message_post", [[order.id]], {
      body: chatterBody,
      message_type: "comment",
    });
  }

  let attachResult = { uploaded: [], errors: [] };
  if (hasAttachments) {
    // Adjuntos al presupuesto (SO); también a tarea si existe.
    const soAttach = await attachDraftFiles(executeKw, "sale.order", order.id, attachments);
    let taskAttach = { uploaded: [], errors: [] };
    if (task?.id) {
      taskAttach = await attachTaskDraftFiles(executeKw, task.id, attachments);
    }
    const seen = new Set();
    const uploaded = [];
    for (const u of [...(soAttach.uploaded || []), ...(taskAttach.uploaded || [])]) {
      const key = `${u.name || ""}:${u.id || u.skipped || ""}`;
      if (seen.has(key)) continue;
      seen.add(key);
      uploaded.push(u);
    }
    attachResult = {
      uploaded,
      errors: [...(soAttach.errors || []), ...(taskAttach.errors || [])],
    };
  }

  const summaryParts = [`${order.name}`];
  if (hasList) summaryParts.push(`${rowCount || 0} filas en nota/lista`);
  if (attachResult.uploaded.length) summaryParts.push(`${attachResult.uploaded.length} adjunto(s)`);
  summaryParts.push(
    productMixChanged ? "SO líneas actualizadas" : hasList ? "SO nota actualizada" : "SO sin cambios de líneas"
  );
  summaryParts.push(`revisión V${String(revision.number).padStart(4, "0")}`);

  return {
    ok: true,
    order: mapped,
    summary: summaryParts.join(" · "),
    attachments_uploaded: attachResult.uploaded.length,
    attachments_errors: attachResult.errors,
    list_mode: listMode || (hasList ? "full" : "attachments_only"),
    product_mix_changed: productMixChanged,
    so_line_updates: soLineUpdates.updates,
    so_line_unmatched: soLineUpdates.unmatched,
    revision,
    excel_warning: EXCEL_VERIFY_WARNING,
  };
}


/**
 * Kapso tool: buscar-pedido-odoo (staff)
 * Usa vars del hilo + mensajes WhatsApp si no hay input explícito.
 */
async function handler(request, env) {
  const body = await request.json().catch(() => ({}));
  const vars = body?.execution_context?.vars || {};
  const now = new Date().toISOString();

  if (vars?.user?.role !== "staff") {
    return json({ ok: false, error: "staff_only" }, 403);
  }
  if (!hasOdooCredentials(env)) {
    return json(odooCredentialsError("buscar-pedido-odoo"));
  }

  try {
    const { executeKw } = await createOdooClient(env);
    const resolved = resolveStaffOrderSearchInput(body);

    if (resolved.already_resolved && resolved.order_id) {
      const bundle = await loadOrderBundle(executeKw, resolved.order_id);
      if (bundle?.mapped) {
        const primary = bundle.mapped;
        return json({
          ok: true,
          status: "ready",
          message: `${primary.order_name} · ${primary.task_stage || "sin etapa"} · ${primary.editable ? "ok" : "bloqueado"}`,
          source: resolved.source,
          orders: [primary],
          vars: buildVars(primary, resolved.source, now),
        });
      }
    }

    if (!resolved.order_number) {
      return json({
        ok: false,
        status: "needs_input",
        message: "Indique el número del pedido (ej. 2564).",
      });
    }

    const result = await searchStaffOrders(executeKw, resolved);
    if (result.note && !result.orders?.length) {
      return json({ ok: false, status: "needs_input", message: result.note });
    }

    const orders = result.orders || [];
    if (!orders.length) {
      return json({
        ok: false,
        status: "not_found",
        message: result.note || "Pedido no encontrado.",
      });
    }

    const primary = orders[0];
    return json({
      ok: true,
      status: "ready",
      message: `${primary.order_name} · ${primary.task_stage || "sin etapa"} · ${primary.editable ? "ok" : "bloqueado"}`,
      source: resolved.source,
      orders,
      vars: buildVars(primary, resolved.source, now),
    });
  } catch (err) {
    return json({ ok: false, error: "odoo_error", message: String(err?.message || err) });
  }
}

function buildVars(primary, source, now) {
  return {
    order_correction: {
      search_status: "ready",
      target_order_id: primary.order_id,
      target_order_name: primary.order_name,
      target_task_id: primary.task_id,
      target_task_stage: primary.task_stage,
      editable: primary.editable,
      lock_reason: primary.lock_reason,
      search_source: source || null,
    },
    order: { id: primary.order_id, name: primary.order_name, status: primary.order_state },
    ...serviceVars("buscar_pedido_odoo", "ready", now, null),
  };
}

function json(payload, status = 200) {
  return new Response(JSON.stringify(payload), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

// ===== clasificar-adjuntos-pedido (69b09b3e-213e-4871-8bcb-3ac0eff31e0b) =====
/**
 * Utilidades compartidas — parse lista pedido staff (tools internas agente).
 */

const FIXED_IMAGE_LIST_QUESTION =
  "Extrae SOLO un JSON array de objetos con keys: numero, nombre, talla, manga, genero (masculino|femenino), arquero (true|false). Sin markdown ni texto extra.";

function compact(value) {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

function digitsOnly(value) {
  return String(value ?? "").replace(/\D/g, "");
}

function normalizeBoolean(value) {
  const text = compact(value).toLowerCase();
  return ["1", "true", "si", "sí", "x", "ok", "yes"].includes(text);
}

/** Marca de casilla Excel (X). Texto libre en la celda no cuenta como marca. */
function isCheckboxMarkValue(value) {
  const t = compact(value).toUpperCase();
  if (!t) return false;
  if (/^\d{2,}$/.test(t)) return false;
  return t === "X" || t === "SI" || t === "SÍ" || t === "1" || t === "TRUE";
}

/** Texto en celda de producto (Camiseta/Uniforme) que no es casilla X. */
function cellInlineNote(value) {
  const t = compact(value);
  if (!t || isCheckboxMarkValue(t)) return "";
  return t;
}

/** Solo pantaloneta / short — no camiseta ni uniforme completo. */
function isPantalonetaOnlyText(...parts) {
  const joined = parts.filter(Boolean).map(compact).join(" ").toLowerCase();
  if (!joined) return false;
  if (
    /solo\s*pantalon|s[oó]lo\s*pantalon|pantaloneta\s*sol|sol[oa]\s+pantaloneta|solo\s+pantaloneta/.test(
      joined
    )
  ) {
    return true;
  }
  if (/\bpantaloneta\b/.test(joined) && /\b(solo|sólo|solamente)\b/.test(joined)) return true;
  return false;
}

function inferAttachmentRole(filename, mimeType = "") {
  const name = compact(filename).toLowerCase();
  const mime = compact(mimeType).toLowerCase();

  if (/\.(xlsx|xlsm|xltx|xls|csv)$/i.test(name) || mime.includes("spreadsheet") || mime.includes("excel")) {
    return "detail_list";
  }
  if (/\.docx$/i.test(name) || mime.includes("wordprocessingml")) {
    return "detail_list";
  }
  if (
    /lista|tallas|formato|pedido|nomin|jugador|alumno|roster|plantel/i.test(name) &&
    /\.(jpe?g|png|webp|pdf)$/i.test(name)
  ) {
    return "detail_list";
  }
  if (/referencia|diseno|diseño|mockup|logo|arte|wildcat|hub/i.test(name)) {
    return "design_reference";
  }
  if (/\.(jpe?g|png|webp|gif)$/i.test(name) || mime.startsWith("image/")) {
    return "design_reference";
  }
  if (/\.pdf$/i.test(name) || mime === "application/pdf") {
    return "detail_list";
  }
  return "other";
}

function pickMediaFromContext(body) {
  const input = body?.input || body?.data || {};
  const vars = body?.execution_context?.vars || {};
  const ctx = body?.whatsapp_context || {};
  const messages = Array.isArray(ctx.messages) ? ctx.messages : [];

  const inbound = [...messages].reverse().filter((m) => m.direction === "inbound");
  const mediaFromMessages = [];
  for (const msg of inbound.slice(0, 12)) {
    const url =
      msg?.media_url ||
      msg?.media?.url ||
      msg?.document?.url ||
      msg?.image?.url ||
      null;
    if (!url || !String(url).startsWith("http")) continue;
    const filename =
      compact(msg?.media?.filename || msg?.document?.filename || msg?.filename) ||
      filenameFromUrl(url);
    const mime = compact(msg?.media?.mime_type || msg?.mimetype || "");
    mediaFromMessages.push({ url, filename, mime_type: mime, role: inferAttachmentRole(filename, mime) });
  }

  const candidates = [
    input.file_url,
    input.media_url,
    input.url,
    vars?.media?.source_url,
    vars?.media?.url,
    ctx?.media_data?.url,
    ctx?.last_media_url,
  ];

  let primaryUrl = null;
  for (const c of candidates) {
    const url = compact(c);
    if (url.startsWith("http")) {
      primaryUrl = url;
      break;
    }
  }

  if (primaryUrl && !mediaFromMessages.some((m) => m.url === primaryUrl)) {
    const filename = compact(input.filename) || filenameFromUrl(primaryUrl);
    const mime = compact(input.mime_type || ctx?.media_data?.mime_type || "");
    mediaFromMessages.unshift({
      url: primaryUrl,
      filename,
      mime_type: mime,
      role: inferAttachmentRole(filename, mime),
    });
  }

  return { primaryUrl, mediaFromMessages };
}

function filenameFromUrl(fileUrl) {
  try {
    const base = new URL(fileUrl).pathname.split("/").pop();
    return base ? decodeURIComponent(base) : "archivo";
  } catch {
    return "archivo";
  }
}

/**
 * Fila canónica para order_draft.detail.rows (compatible build_odoo_order_note).
 */
function toDetailRow(raw) {
  if (!raw || typeof raw !== "object") return null;

  const numero = compact(raw.numero || raw.number || raw.dorsal || raw.n);
  const arqueroFromRaw =
    normalizeBoolean(raw.arquero || raw.ARQUERO) ||
    (!raw.pantaloneta && /arquer|porter/i.test(compact(raw.rol || raw.comentario || "")));

  let nombre = compact(raw.nombre || raw.name || raw.nombre_uniforme);
  const tallaEarly = compact(raw.talla || raw.size || raw.TALLA);
  const isUniformeRow =
    !normalizeBoolean(raw.pantaloneta) &&
    !normalizeBoolean(raw.camiseta) &&
    (normalizeBoolean(raw.uniforme) || raw.uniforme !== false);
  const intentionalBlankName = normalizeBoolean(raw.nombre_vacio_impresion);

  if (!nombre && arqueroFromRaw && numero) nombre = `Arquero #${numero}`;
  if (!nombre && arqueroFromRaw) nombre = "Arquero";
  if (!nombre && numero && normalizeBoolean(raw.camiseta)) nombre = `Camiseta #${numero}`;
  if (!nombre && intentionalBlankName && isUniformeRow && (numero || tallaEarly)) {
    nombre = "";
  }
  if (!nombre && !numero && !tallaEarly) return null;

  const talla = compact(raw.talla || raw.size || raw.TALLA);
  const manga = compact(raw.manga || raw.sleeve || raw["Larga/Corta"] || raw.manga_variante);

  let grupo = compact(raw.grupo || raw.genero || raw.gender || raw.GENERO).toLowerCase();
  if (/fem|mujer/.test(grupo)) grupo = "femenino";
  else if (/masc|hombre|varon/.test(grupo)) grupo = "masculino";
  else if (!grupo && normalizeBoolean(raw.fem || raw.FEM)) grupo = "femenino";
  else if (!grupo && normalizeBoolean(raw.mas || raw.MAS)) grupo = "masculino";
  else if (!grupo) grupo = "general";

  const comentario = compact(raw.comentario || "");
  const pantaloneta =
    normalizeBoolean(raw.pantaloneta) ||
    isPantalonetaOnlyText(comentario, raw.rol, raw.nota_celda);

  let rol = compact(
    raw.rol || raw.role || raw.variante || raw.curso_equipo || raw.equipo || raw.grupo_detalle
  );
  if (pantaloneta) {
    const notes = comentario
      .split(" · ")
      .map((s) => s.trim())
      .filter((s) => s && !/^solo\s*pantaloneta$/i.test(s));
    const unique = [...new Set(notes)];
    rol = unique.length ? `Pantaloneta · ${unique.join(" · ")}` : "Pantaloneta";
  } else if (!rol) {
    const parts = [];
    if (normalizeBoolean(raw.camiseta)) parts.push("Camiseta");
    else if (normalizeBoolean(raw.uniforme) || raw.uniforme === undefined) {
      if (raw.uniforme !== false) parts.push("Uniforme");
    }
    if (comentario) parts.push(comentario);
    rol = parts.join(" · ");
  } else if (comentario && !rol.includes(comentario)) {
    rol = `${rol} · ${comentario}`;
  }

  const arquero =
    !pantaloneta && (arqueroFromRaw || /arquer|porter/i.test(rol));

  return {
    person_id: compact(raw.person_id || raw.personId || "") || null,
    numero: numero || "",
    nombre,
    talla: talla || "",
    grupo,
    rol: rol || "",
    manga: manga || "",
    arquero,
    camiseta: pantaloneta ? false : normalizeBoolean(raw.camiseta),
    uniforme: pantaloneta ? false : raw.uniforme !== false && !normalizeBoolean(raw.camiseta),
    pantaloneta,
    comentario,
    nombre_vacio_impresion: intentionalBlankName && !nombre,
    impresion_delantera: compact(raw.impresion_delantera || "") || null,
    impresion_trasera: compact(raw.impresion_trasera || "") || null,
    product_line_key: compact(raw.product_line_key || raw.section_key || "") || null,
    product_text: compact(raw.product_text || "") || null,
    garment_type: compact(raw.garment_type || "") || null,
    category: compact(raw.category || "") || null,
    variant_notes: compact(raw.variant_notes || "") || null,
  };
}

function componentTypeFromRow(row) {
  if (row.pantaloneta) return "pantaloneta";
  if (row.camiseta) return "camiseta";
  if (row.uniforme) return "uniforme_completo";
  return row.garment_type || "prenda";
}

function detailRowsToPeople(rows) {
  const people = [];
  const byId = new Map();
  (Array.isArray(rows) ? rows : []).forEach((raw, index) => {
    const row = toDetailRow(raw);
    if (!row) return;
    const personId = row.person_id || `row-${index + 1}`;
    let person = byId.get(personId);
    if (!person) {
      person = {
        person_id: personId,
        identity: {
          display_name: row.nombre || null,
          print_name: row.nombre || null,
          number: row.numero || null,
          group: row.grupo || "general",
        },
        components: [],
        comments: [],
      };
      byId.set(personId, person);
      people.push(person);
    }
    person.components.push({
      type: componentTypeFromRow(row),
      size: row.talla || null,
      sleeve: row.manga || null,
      goalkeeper: Boolean(row.arquero),
      product_line_key: row.product_line_key,
      product_text: row.product_text,
      garment_type: row.garment_type,
      category: row.category,
      variant_notes: row.variant_notes,
      printing: {
        front: row.impresion_delantera,
        back: row.impresion_trasera,
      },
      comment: row.comentario || null,
    });
    if (row.comentario && !person.comments.includes(row.comentario)) {
      person.comments.push(row.comentario);
    }
  });
  return people;
}

function peopleToDetailRows(people) {
  const rows = [];
  for (const person of Array.isArray(people) ? people : []) {
    const identity = person?.identity || {};
    const components = Array.isArray(person?.components) ? person.components : [];
    for (const component of components) {
      const type = compact(component?.type).toLowerCase();
      rows.push(
        toDetailRow({
          person_id: compact(person.person_id) || null,
          nombre: identity.print_name ?? identity.display_name,
          numero: identity.number,
          genero: identity.group,
          talla: component?.size,
          manga: component?.sleeve,
          arquero: component?.goalkeeper,
          camiseta: type === "camiseta" || type === "camiseta_sola",
          uniforme: type === "uniforme" || type === "uniforme_completo",
          pantaloneta: type === "pantaloneta",
          comentario: component?.comment || (person.comments || []).join(" · "),
          impresion_delantera: component?.printing?.front,
          impresion_trasera: component?.printing?.back,
          product_line_key: component?.product_line_key,
          product_text: component?.product_text,
          garment_type: component?.garment_type || type,
          category: component?.category,
          variant_notes: component?.variant_notes,
        })
      );
    }
  }
  return rows.filter(Boolean);
}

function buildDetailSummary(rows) {
  if (!Array.isArray(rows) || !rows.length) {
    return "Sin filas de lista parseadas.";
  }
  const masc = rows.filter((r) => r.grupo === "masculino").length;
  const fem = rows.filter((r) => r.grupo === "femenino").length;
  const general = rows.length - masc - fem;
  const parts = [`${rows.length} filas`];
  if (masc) parts.push(`${masc} M`);
  if (fem) parts.push(`${fem} F`);
  if (general) parts.push(`${general} general`);
  const missingTalla = rows.filter((r) => !r.talla).length;
  const missingNum = rows.filter((r) => !r.numero).length;
  if (missingTalla) parts.push(`${missingTalla} sin talla`);
  if (missingNum) parts.push(`${missingNum} sin número`);
  return parts.join(" · ");
}

function mergeAttachments(existing, incoming) {
  const out = Array.isArray(existing) ? [...existing] : [];
  const seen = new Set(out.map((a) => `${a.url}|${a.filename}`));
  for (const att of incoming || []) {
    const url = compact(att?.url);
    if (!url.startsWith("http")) continue;
    const key = `${url}|${compact(att.filename)}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({
      url,
      filename: compact(att.filename) || filenameFromUrl(url),
      mime_type: compact(att.mime_type) || null,
      role: att.role || inferAttachmentRole(att.filename, att.mime_type),
    });
  }
  return out;
}

function mergeDetailRows(existing, incoming, mode = "replace") {
  const oldRows = Array.isArray(existing) ? existing.map(toDetailRow).filter(Boolean) : [];
  const newRows = Array.isArray(incoming) ? incoming.map(toDetailRow).filter(Boolean) : [];
  if (mode === "append") {
    const key = (r) => `${r.numero}|${r.nombre}|${r.talla}`.toLowerCase();
    const seen = new Set(oldRows.map(key));
    const merged = [...oldRows];
    for (const row of newRows) {
      const k = key(row);
      if (seen.has(k)) continue;
      seen.add(k);
      merged.push(row);
    }
    return merged;
  }
  return newRows.length ? newRows : oldRows;
}

function buildWarnings(rows) {
  const warnings = [];
  if (!rows.length) warnings.push("No hay filas en la lista.");
  rows.forEach((row, idx) => {
    if (!row.talla) warnings.push(`Fila ${idx + 1} (${row.nombre}): sin talla`);
    if (!row.numero) warnings.push(`Fila ${idx + 1} (${row.nombre}): sin número`);
  });
  return warnings;
}

function parseStatusFrom(rows, warnings) {
  if (!rows.length) return "needs_review";
  const critical = warnings.some((w) => /sin talla|sin número|No hay filas/i.test(w));
  if (critical && rows.length < 3) return "needs_review";
  if (warnings.length) return "partial";
  return "ok";
}

function patchOrderDraft(vars, patch) {
  const prev = vars?.order_draft || {};
  const detail = { ...(prev.detail || {}), ...(patch.detail || {}) };
  if (patch.detail?.rows) detail.rows = patch.detail.rows;
  return {
    ...prev,
    ...patch,
    detail,
    attachments: patch.attachments ?? prev.attachments ?? [],
    blockers: patch.blockers ?? prev.blockers ?? [],
  };
}

function serviceVars(name, status, now, fallback = null) {
  return {
    service: {
      last_call_name: name,
      last_call_status: status,
      last_call_at: now,
      fallback_message: fallback,
    },
  };
}

function jsonResponse(payload, status = 200) {
  return new Response(JSON.stringify(payload), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

async function fetchBinary(fileUrl) {
  const resp = await fetch(fileUrl);
  if (!resp.ok) throw new Error(`download_failed:${resp.status}`);
  return new Uint8Array(await resp.arrayBuffer());
}


/**
 * Kapso tool: clasificar-adjuntos-pedido
 */
function suggestTools(attachments) {
  const tools = [];
  const hasListFile = attachments.some(
    (a) =>
      a.role === "detail_list" &&
      /\.(xlsx|xls|docx)|spreadsheet|wordprocessing/i.test(`${a.filename || ""}${a.mime_type || ""}`)
  );
  const hasListImage = attachments.some((a) => a.role === "detail_list" && /\.(jpe?g|png|webp|pdf)$/i.test(a.filename || ""));
  const hasDesign = attachments.some((a) => a.role === "design_reference");

  if (hasListFile) tools.push("parsear_lista_excel_pedido");
  if (hasListImage) tools.push("parsear_lista_imagen_pedido");
  if (attachments.length) tools.push("registrar_adjuntos_pedido");
  if (hasDesign && !hasListFile && !hasListImage) tools.push("registrar_adjuntos_pedido");

  return [...new Set(tools)];
}

async function handler(request, env) {
  const body = await request.json().catch(() => ({}));
  const vars = body?.execution_context?.vars || {};
  const now = new Date().toISOString();

  if (vars?.user?.role !== "staff") {
    return jsonResponse({ ok: false, error: "staff_only" }, 403);
  }

  const { mediaFromMessages } = pickMediaFromContext(body);
  const attachments = mergeAttachments(vars?.order_draft?.attachments, mediaFromMessages);
  const suggested_tools = suggestTools(attachments);

  const order_draft = patchOrderDraft(vars, { attachments });

  return jsonResponse({
    ok: true,
    attachment_count: attachments.length,
    attachments,
    suggested_tools,
    vars: {
      order_draft,
      ...serviceVars("clasificar_adjuntos_pedido", "ready", now, null),
    },
  });
}

// ===== classify-contact-odoo (93d89e4c-603b-49fc-96f9-0b1c13df86be) =====
/**
 * Búsqueda de res.partner por teléfono WhatsApp (Odoo 19 prod).
 * Usar phone_sanitized / phone_mobile_search; phone visible suele tener espacios.
 */

function digitsOnly(value) {
  return String(value ?? "").replace(/\D/g, "");
}

function normalizeWaPhone(raw) {
  const digits = digitsOnly(raw);
  if (!digits) {
    return { e164Plus: null, e164Digits: null, local10: null, raw: String(raw ?? "").trim() };
  }

  let national = digits;
  if (digits.startsWith("57") && digits.length >= 12) {
    national = digits.slice(-10);
  } else if (digits.length >= 10) {
    national = digits.slice(-10);
  } else {
    return { e164Plus: null, e164Digits: null, local10: null, raw: String(raw ?? "").trim() };
  }

  return {
    e164Plus: `+57${national}`,
    e164Digits: `57${national}`,
    local10: national,
    raw: String(raw ?? "").trim(),
  };
}

const ACTIVE_PARTNER = ["active", "=", true];

function partnerSearchDomains(normalized) {
  if (!normalized?.e164Plus) return [];
  const { e164Plus, e164Digits, local10 } = normalized;
  return [
    { strategy: "phone_sanitized", domain: [ACTIVE_PARTNER, ["phone_sanitized", "=", e164Plus]] },
    { strategy: "phone_mobile_search_plus", domain: [ACTIVE_PARTNER, ["phone_mobile_search", "=", e164Plus]] },
    { strategy: "phone_mobile_search_digits", domain: [ACTIVE_PARTNER, ["phone_mobile_search", "=", e164Digits]] },
    { strategy: "phone_exact_digits", domain: [ACTIVE_PARTNER, ["phone", "=", e164Digits]] },
    { strategy: "phone_ilike_local10", domain: [ACTIVE_PARTNER, ["phone", "ilike", local10]] },
  ];
}

function mergePartnerCandidates(existing, rows) {
  const seen = new Set(existing.map((row) => row.id));
  const merged = [...existing];
  for (const row of rows || []) {
    if (!row?.id || seen.has(row.id)) continue;
    seen.add(row.id);
    merged.push(row);
  }
  return merged;
}

function pickPartnerByLatestOrder(candidates, orders) {
  if (!Array.isArray(candidates) || candidates.length === 0) return null;
  if (candidates.length === 1) return candidates[0];

  const orderList = Array.isArray(orders) ? orders : [];
  for (const order of orderList) {
    const partnerId = Array.isArray(order?.partner_id) ? order.partner_id[0] : order?.partner_id;
    const hit = candidates.find((candidate) => candidate.id === partnerId);
    if (hit) return hit;
  }

  return [...candidates].sort((a, b) => a.id - b.id)[0];
}

/**
 * @param {(model: string, method: string, args: unknown[], kw?: object) => Promise<unknown>} executeKw
 */
async function findPartnerByWaPhone(executeKw, rawPhone, options = {}) {
  const normalized = normalizeWaPhone(rawPhone);
  if (!normalized.e164Plus) {
    return {
      partner: null,
      normalized,
      match_strategy: null,
      ambiguous: false,
      candidates: [],
    };
  }

  const fields = options.fields || ["id", "name", "phone", "phone_sanitized"];
  let candidates = [];
  let match_strategy = null;

  for (const { strategy, domain } of partnerSearchDomains(normalized)) {
    const rows = await executeKw("res.partner", "search_read", [domain], {
      fields,
      limit: options.limit || 10,
    });
    const before = candidates.length;
    candidates = mergePartnerCandidates(candidates, rows);
    if (candidates.length === 1 && before === 0) {
      match_strategy = strategy;
      return {
        partner: candidates[0],
        normalized,
        match_strategy,
        ambiguous: false,
        candidates: summarizeCandidates(candidates),
      };
    }
    if (candidates.length > 0 && !match_strategy) {
      match_strategy = strategy;
    }
  }

  if (candidates.length === 0) {
    return {
      partner: null,
      normalized,
      match_strategy: null,
      ambiguous: false,
      candidates: [],
    };
  }

  if (candidates.length === 1) {
    return {
      partner: candidates[0],
      normalized,
      match_strategy,
      ambiguous: false,
      candidates: summarizeCandidates(candidates),
    };
  }

  const ids = candidates.map((candidate) => candidate.id);
  const saleOrders = await executeKw(
    "sale.order",
    "search_read",
    [[["partner_id", "in", ids]]],
    {
      fields: ["id", "name", "partner_id", "date_order", "state"],
      order: "date_order desc, id desc",
      limit: 50,
    }
  );

  const partner = pickPartnerByLatestOrder(candidates, saleOrders);
  return {
    partner,
    normalized,
    match_strategy: "disambiguate_latest_order",
    ambiguous: true,
    candidates: summarizeCandidates(candidates),
    chosen_partner_id: partner?.id || null,
  };
}

function summarizeCandidates(candidates) {
  return (candidates || []).map((candidate) => ({
    id: candidate.id,
    name: candidate.name,
    phone: candidate.phone || null,
    phone_sanitized: candidate.phone_sanitized || null,
  }));
}

function partnerCreateVals(displayName, normalized, extra = {}) {
  return {
    name: displayName,
    phone: normalized?.e164Plus || false,
    comment: extra.comment || false,
  };
}

function nameSearchTerms(rawName) {
  const name = String(rawName ?? "").trim();
  if (!name) return [];
  const terms = [name];
  const preseas = name.match(/preseas\s*#?\s*(\d+)/i);
  if (preseas) {
    terms.push(`PRESEAS ${preseas[1]}`);
    terms.push(`PRESEAS #${preseas[1]}`);
    terms.push("PRESEAS");
  }
  return [...new Set(terms.map((t) => t.trim()).filter(Boolean))];
}

/**
 * @param {(model: string, method: string, args: unknown[], kw?: object) => Promise<unknown>} executeKw
 */
async function findPartnerByName(executeKw, rawName, options = {}) {
  const terms = nameSearchTerms(rawName);
  if (!terms.length) {
    return {
      partner: null,
      match_strategy: null,
      ambiguous: false,
      candidates: [],
    };
  }

  const fields = options.fields || ["id", "name", "phone", "phone_sanitized"];
  let candidates = [];
  let match_strategy = null;

  for (const term of terms) {
    const rows = await executeKw(
      "res.partner",
      "search_read",
      [[ACTIVE_PARTNER, ["name", "ilike", term]]],
      { fields, limit: options.limit || 10 }
    );
    const before = candidates.length;
    candidates = mergePartnerCandidates(candidates, rows);
    if (candidates.length === 1 && before === 0) {
      match_strategy = `name_ilike:${term}`;
      return {
        partner: candidates[0],
        match_strategy,
        ambiguous: false,
        candidates: summarizeCandidates(candidates),
      };
    }
    if (candidates.length > 0 && !match_strategy) {
      match_strategy = `name_ilike:${term}`;
    }
  }

  if (candidates.length === 0) {
    return {
      partner: null,
      match_strategy: null,
      ambiguous: false,
      candidates: [],
    };
  }

  if (candidates.length === 1) {
    return {
      partner: candidates[0],
      match_strategy,
      ambiguous: false,
      candidates: summarizeCandidates(candidates),
    };
  }

  const ids = candidates.map((candidate) => candidate.id);
  const saleOrders = await executeKw(
    "sale.order",
    "search_read",
    [[["partner_id", "in", ids]]],
    {
      fields: ["id", "name", "partner_id", "date_order", "state"],
      order: "date_order desc, id desc",
      limit: 50,
    }
  );

  const partner = pickPartnerByLatestOrder(candidates, saleOrders);
  return {
    partner,
    match_strategy: "disambiguate_latest_order_by_name",
    ambiguous: true,
    candidates: summarizeCandidates(candidates),
    chosen_partner_id: partner?.id || null,
  };
}


/**
 * Contrato quote rico + plantilla LIFE_DOSSIER_v1 (pedido vivo multi-semana).
 * Fuente de verdad corta: vars.quote (Kapso).
 * Fuente de verdad larga: descripción oportunidad CRM con bloque LIFE_DOSSIER_v1.
 */

const DOSSIER_MARKER = "LIFE_DOSSIER_v1";

function compact(value) {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function num(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

/** ¿El quote tiene suficiente señal comercial para hidratar? */
function quoteLooksUseful(quote = {}) {
  if (!quote || typeof quote !== "object") return false;
  if (asArray(quote.lines).some((l) => compact(l.product_text) || num(l.quantity) > 0)) {
    return true;
  }
  return Boolean(
    compact(quote.product_text) ||
      num(quote.quantity) > 0 ||
      num(quote.unit_cop) > 0 ||
      compact(quote.customer_display_name) ||
      compact(quote.notes) ||
      asArray(quote.media_refs).length > 0
  );
}

/** Peso para elegir el mejor quote entre ejecuciones. */
function quoteRichnessScore(quote = {}) {
  if (!quoteLooksUseful(quote)) return 0;
  let score = 0;
  if (compact(quote.product_text)) score += 2;
  if (num(quote.quantity) > 0) score += 2;
  if (num(quote.unit_cop) > 0) score += 1;
  if (num(quote.total_cop) > 0) score += 1;
  score += Math.min(4, asArray(quote.lines).length * 2);
  if (quote.variants && typeof quote.variants === "object") {
    score += Object.values(quote.variants).filter((v) => compact(v)).length;
  }
  if (compact(quote.notes)) score += 2;
  score += Math.min(3, asArray(quote.media_refs).length);
  if (compact(quote.dossier_text) || compact(quote.status)) score += 1;
  return score;
}

/**
 * Normaliza quote legado (solo product_text) a shape rico.
 * No inventa líneas: si no hay lines[], crea una desde product_text cuando hay qty/precio.
 */
function normalizeQuote(quote = {}, options = {}) {
  const now = options.now || new Date().toISOString();
  const base = quote && typeof quote === "object" ? { ...quote } : {};
  let lines = asArray(base.lines)
    .map((line) => ({
      product_text: compact(line.product_text || line.product || line.name) || null,
      quantity: num(line.quantity ?? line.qty),
      unit_cop: num(line.unit_cop ?? line.unit),
      total_cop: num(line.total_cop ?? line.total),
      odoo_product_id: line.odoo_product_id ?? null,
      garment_type: compact(line.garment_type) || null,
    }))
    .filter((l) => l.product_text || l.quantity || l.unit_cop);

  const productText = compact(base.product_text || base.product) || null;
  const quantity = num(base.quantity ?? base.qty);
  const unitCop = num(base.unit_cop ?? base.unit);
  const totalCop = num(base.total_cop ?? base.total);

  if (!lines.length && (productText || quantity || unitCop)) {
    lines = [
      {
        product_text: productText,
        quantity,
        unit_cop: unitCop,
        total_cop: totalCop,
        odoo_product_id: base.odoo_product_id ?? null,
        garment_type: compact(base.garment_type) || null,
      },
    ];
  }

  const variants =
    base.variants && typeof base.variants === "object"
      ? {
          material: compact(base.variants.material || base.material) || null,
          collar: compact(base.variants.collar || base.collar || base.variant) || null,
          sleeves: compact(base.variants.sleeves || base.sleeves) || null,
          sport: compact(base.variants.sport || base.sport) || null,
        }
      : {
          material: compact(base.material) || null,
          collar: compact(base.collar || base.variant) || null,
          sleeves: compact(base.sleeves) || null,
          sport: compact(base.sport) || null,
        };

  const media_refs = asArray(base.media_refs)
    .map((m) => ({
      url: compact(m.url) || null,
      summary: compact(m.summary || m.photo_summary) || null,
      role: compact(m.role) || "design",
      at: compact(m.at) || null,
    }))
    .filter((m) => m.url || m.summary);

  const history = asArray(base.history)
    .map((h) => ({
      at: compact(h.at) || null,
      note: compact(h.note || h.text) || null,
    }))
    .filter((h) => h.note);

  const primary = lines[0] || {};
  const revision = Number(base.revision || 0) || (quoteLooksUseful(base) ? 1 : 0);

  return {
    ...base,
    product_text: productText || primary.product_text || null,
    quantity: quantity ?? primary.quantity ?? null,
    unit_cop: unitCop ?? primary.unit_cop ?? null,
    total_cop: totalCop ?? primary.total_cop ?? null,
    odoo_product_id: base.odoo_product_id ?? primary.odoo_product_id ?? null,
    match_confidence: compact(base.match_confidence) || null,
    lines,
    variants,
    notes: compact(base.notes) || null,
    media_refs,
    history,
    status:
      compact(base.status) ||
      (quoteLooksUseful(base) ? "cotizando" : null),
    revision,
    updated_at: compact(base.updated_at) || now,
    dossier_text: compact(base.dossier_text) || null,
  };
}

/** Fusiona prior + next privilegiando next en campos escalares y uniendo lines/media/history. */
function mergeQuotes(prior, next, options = {}) {
  const now = options.now || new Date().toISOString();
  const a = normalizeQuote(prior || {}, { now });
  const b = normalizeQuote(next || {}, { now });
  if (!quoteLooksUseful(a) && !quoteLooksUseful(b)) return normalizeQuote({}, { now });
  if (!quoteLooksUseful(b)) return a;
  if (!quoteLooksUseful(a)) return { ...b, revision: Math.max(1, b.revision || 1), updated_at: now };

  const lineKey = (l) =>
    `${compact(l.product_text).toLowerCase()}|${l.quantity || ""}|${l.unit_cop || ""}`;
  const lineMap = new Map();
  for (const l of a.lines) lineMap.set(lineKey(l), l);
  for (const l of b.lines) lineMap.set(lineKey(l), l);
  const lines = [...lineMap.values()];

  const mediaMap = new Map();
  for (const m of [...a.media_refs, ...b.media_refs]) {
    const key = m.url || m.summary;
    if (key) mediaMap.set(key, m);
  }

  const history = [...a.history, ...b.history].slice(-20);
  const bump =
    options.bumpRevision === true ||
    a.quantity !== b.quantity ||
    a.product_text !== b.product_text ||
    a.lines.length !== b.lines.length;

  const merged = normalizeQuote(
    {
      ...a,
      ...b,
      product_text: b.product_text || a.product_text,
      quantity: b.quantity ?? a.quantity,
      unit_cop: b.unit_cop ?? a.unit_cop,
      total_cop: b.total_cop ?? a.total_cop,
      odoo_product_id: b.odoo_product_id ?? a.odoo_product_id,
      match_confidence: b.match_confidence || a.match_confidence,
      lines,
      variants: {
        material: b.variants.material || a.variants.material,
        collar: b.variants.collar || a.variants.collar,
        sleeves: b.variants.sleeves || a.variants.sleeves,
        sport: b.variants.sport || a.variants.sport,
      },
      notes: [a.notes, b.notes].filter(Boolean).join(" · ") || null,
      media_refs: [...mediaMap.values()],
      history,
      status: b.status || a.status || "cotizando",
      revision: bump ? Math.max(a.revision || 0, b.revision || 0) + 1 : Math.max(a.revision || 1, b.revision || 1),
      updated_at: now,
    },
    { now }
  );
  merged.dossier_text = buildDossierText(merged);
  return merged;
}

function money(n) {
  const v = num(n);
  if (!v) return null;
  return `$${Math.round(v).toLocaleString("es-CO")}`;
}

/** Texto plano LIFE_DOSSIER_v1 para CRM description / notify. */
function buildDossierText(quoteInput = {}, meta = {}) {
  const q = normalizeQuote(quoteInput);
  const lines = [
    DOSSIER_MARKER,
    `cliente: ${compact(meta.customer_name || q.customer_display_name) || "—"}`,
    `telefono: ${compact(meta.customer_phone) || "—"}`,
    `estado: ${compact(q.status) || "cotizando"}`,
    `revision: ${q.revision || 1}`,
    `updated_at: ${compact(q.updated_at) || new Date().toISOString()}`,
    `qty: ${q.quantity ?? "—"}`,
  ];

  if (q.lines.length) {
    lines.push("opciones:");
    for (const l of q.lines) {
      const unit = money(l.unit_cop);
      const total = money(l.total_cop);
      const priceBit =
        unit && total ? `${unit} → ${total}` : unit || total || "sin precio";
      lines.push(
        `  - ${l.product_text || "producto"}${l.quantity != null ? ` x${l.quantity}` : ""}: ${priceBit}`
      );
    }
  } else if (q.product_text) {
    lines.push("opciones:");
    const unit = money(q.unit_cop);
    const total = money(q.total_cop);
    const priceBit =
      unit && total ? `${unit} → ${total}` : unit || total || "sin precio";
    lines.push(
      `  - ${q.product_text}${q.quantity != null ? ` x${q.quantity}` : ""}: ${priceBit}`
    );
  }

  const v = q.variants || {};
  const variantBits = [v.material, v.collar, v.sleeves, v.sport].filter(Boolean);
  if (variantBits.length) lines.push(`variantes: ${variantBits.join(", ")}`);
  if (q.notes) lines.push(`personalizacion: ${q.notes}`);
  if (q.media_refs.length) {
    lines.push("media:");
    for (const m of q.media_refs.slice(0, 8)) {
      lines.push(`  - [${m.role}] ${m.summary || m.url || "ref"}`);
    }
  }
  if (q.history.length) {
    lines.push("historial:");
    for (const h of q.history.slice(-10)) {
      lines.push(`  - ${h.at || "—"}: ${h.note}`);
    }
  }
  return lines.join("\n");
}

/** Extrae bloque LIFE_DOSSIER_v1 de HTML o texto (descripción CRM). */
function parseDossierFromDescription(description) {
  const raw = String(description || "")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&");
  const idx = raw.indexOf(DOSSIER_MARKER);
  if (idx < 0) return null;
  const block = raw.slice(idx).split(/\n(?=[A-Z_]{3,}:)/)[0] || raw.slice(idx);
  // Take until blank double-newline or end; keep indented lines
  const body = raw.slice(idx);
  const endMatch = body.search(/\n\n(?!  -)/);
  const text = (endMatch > 0 ? body.slice(0, endMatch) : body).trim();

  const get = (key) => {
    const re = new RegExp(`^${key}:\\s*(.+)$`, "im");
    const m = text.match(re);
    return m ? compact(m[1]) : null;
  };

  const lines = [];
  const optSection = text.match(/opciones:\n((?:  - .+\n?)+)/i);
  if (optSection) {
    for (const row of optSection[1].split("\n")) {
      const m = row.match(/^\s*-\s*(.+?)(?:\s+x(\d+))?:\s*(.+)$/);
      if (!m) continue;
      const product_text = compact(m[1]);
      const quantity = m[2] ? Number(m[2]) : null;
      const priceRaw = compact(m[3]);
      let unit_cop = null;
      let total_cop = null;
      const prices = [...priceRaw.matchAll(/\$?\s*([\d.]+)/g)].map((x) =>
        Number(String(x[1]).replace(/\./g, ""))
      );
      if (prices.length >= 2) {
        unit_cop = prices[0];
        total_cop = prices[1];
      } else if (prices.length === 1) {
        unit_cop = prices[0];
      }
      lines.push({ product_text, quantity, unit_cop, total_cop });
    }
  }

  const variantsRaw = get("variantes");
  const variants = { material: null, collar: null, sleeves: null, sport: null };
  if (variantsRaw) {
    const parts = variantsRaw.split(",").map((p) => compact(p).toLowerCase());
    for (const p of parts) {
      if (/dry|dumonti|hidrotec|lluvia/.test(p)) variants.material = p;
      else if (/cuello|polo|redondo|sport|\bv\b/.test(p)) variants.collar = p;
      else if (/manga/.test(p)) variants.sleeves = p;
      else if (/futbol|voleibol|baloncesto|atletismo/.test(p)) variants.sport = p;
    }
  }

  const media_refs = [];
  const mediaSection = text.match(/media:\n((?:  - .+\n?)+)/i);
  if (mediaSection) {
    for (const row of mediaSection[1].split("\n")) {
      const m = row.match(/^\s*-\s*\[([^\]]+)\]\s*(.+)$/);
      if (m) media_refs.push({ role: compact(m[1]), summary: compact(m[2]), url: null });
    }
  }

  const history = [];
  const histSection = text.match(/historial:\n((?:  - .+\n?)+)/i);
  if (histSection) {
    for (const row of histSection[1].split("\n")) {
      const m = row.match(/^\s*-\s*([^:]+):\s*(.+)$/);
      if (m) history.push({ at: compact(m[1]), note: compact(m[2]) });
    }
  }

  const primary = lines[0] || {};
  return normalizeQuote({
    product_text: primary.product_text || null,
    quantity: num(get("qty")) ?? primary.quantity,
    unit_cop: primary.unit_cop,
    total_cop: primary.total_cop,
    lines,
    variants,
    notes: get("personalizacion"),
    media_refs,
    history,
    status: get("estado") || "cotizando",
    revision: num(get("revision")) || 1,
    updated_at: get("updated_at"),
    customer_display_name: get("cliente"),
    dossier_text: text,
  });
}

/**
 * Inserta o reemplaza bloque LIFE_DOSSIER_v1 en descripción CRM (HTML o texto).
 */
function mergeDescriptionWithDossier(existingDescription, quote, meta = {}) {
  const dossier = buildDossierText(quote, meta);
  const existing = String(existingDescription || "");
  const plainExisting = existing
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, "");
  const idx = plainExisting.indexOf(DOSSIER_MARKER);
  const dossierHtml = `<pre>${dossier.replace(/</g, "&lt;")}</pre>`;
  if (idx < 0) {
    if (!existing.trim()) return dossierHtml;
    return `${existing}\n\n${dossierHtml}`;
  }
  // Replace previous dossier block in HTML by rewriting whole description: keep non-dossier parts
  const without = existing.replace(
    /<pre>[\s\S]*?LIFE_DOSSIER_v1[\s\S]*?<\/pre>/i,
    ""
  ).replace(/LIFE_DOSSIER_v1[\s\S]*?(?=\n\n|$)/, "");
  return `${without.trim()}\n\n${dossierHtml}`.trim();
}

/** Resumen corto para el agente al retomar. */
function continuityResumeHint(quoteInput = {}) {
  const q = normalizeQuote(quoteInput);
  if (!quoteLooksUseful(q)) return null;
  const bits = [];
  if (q.quantity && q.product_text) bits.push(`${q.quantity} × ${q.product_text}`);
  else if (q.product_text) bits.push(q.product_text);
  const v = q.variants || {};
  const vars = [v.material, v.collar, v.sleeves].filter(Boolean);
  if (vars.length) bits.push(vars.join(", "));
  if (q.lines.length > 1) {
    bits.push(
      `opciones: ${q.lines.map((l) => l.product_text || "línea").join(" / ")}`
    );
  }
  const unit = money(q.unit_cop);
  const total = money(q.total_cop);
  if (unit && total) bits.push(`${unit} c/u · ${total} total`);
  else if (unit) bits.push(`${unit} c/u`);
  return bits.join(" · ");
}


/**
 * Retoma quote/contexto comercial entre conversaciones Kapso.
 * Cuando WhatsApp Business cierra el hilo (ended) y abre uno nuevo,
 * la ejecución anterior muere; este helper busca por teléfono la última
 * ejecución con quote útil y la reinyecta.
 */


function kapsoConfig(env = {}) {
  const base = String(env.KAPSO_API_BASE_URL || "").replace(/\/$/, "");
  const key = String(env.KAPSO_API_KEY || "").trim();
  const workflowId = String(
    env.KAPSO_WORKFLOW_ID || "8995b14c-d852-4fb3-bceb-8a51a6ccc2c6"
  ).trim();
  if (!base || !key) return null;
  return { base, key, workflowId };
}

async function kapsoGet(cfg, path, query = {}) {
  const url = new URL(`${cfg.base}${path}`);
  for (const [k, v] of Object.entries(query)) {
    if (v == null || v === "") continue;
    url.searchParams.set(k, String(v));
  }
  const resp = await fetch(url.toString(), {
    method: "GET",
    headers: {
      Accept: "application/json",
      "X-API-Key": cfg.key,
    },
  });
  const json = await resp.json().catch(() => ({}));
  if (!resp.ok) {
    throw new Error(`kapso_${resp.status}:${json?.error || resp.statusText}`);
  }
  return json?.data ?? json;
}

function unwrapList(payload) {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.conversations)) return payload.conversations;
  if (Array.isArray(payload?.whatsapp_conversations)) {
    return payload.whatsapp_conversations;
  }
  if (Array.isArray(payload?.executions)) return payload.executions;
  return [];
}

/** Digits-only compare; require local-10 overlap so we never hydrate another WA. */
function conversationMatchesPhone(conversation, phoneDigits) {
  const want = String(phoneDigits || "").replace(/\D/g, "");
  if (!want) return false;
  const got = String(
    conversation?.phone_number ||
      conversation?.phone ||
      conversation?.wa_id ||
      ""
  ).replace(/\D/g, "");
  if (!got) return false;
  if (got === want) return true;
  const wantLocal = want.length >= 10 ? want.slice(-10) : want;
  const gotLocal = got.length >= 10 ? got.slice(-10) : got;
  return wantLocal.length >= 10 && wantLocal === gotLocal;
}

/**
 * @returns {Promise<null|{
 *   quote: object,
 *   funnel: object|null,
 *   order_focus: object|null,
 *   source: { conversation_id: string, execution_id: string, status: string }
 * }>}
 */
async function hydrateCustomerSessionFromKapso(env, phone, options = {}) {
  const cfg = kapsoConfig(env);
  if (!cfg) {
    return {
      ok: false,
      error: "missing_kapso_secrets",
      quote: null,
      funnel: null,
      order_focus: null,
      source: null,
    };
  }

  const phoneDigits = String(phone ?? "").replace(/\D/g, "");
  if (!phoneDigits) {
    return {
      ok: false,
      error: "missing_phone",
      quote: null,
      funnel: null,
      order_focus: null,
      source: null,
    };
  }

  const currentConversationId = String(options.currentConversationId || "").trim();
  const currentExecutionId = String(options.currentExecutionId || "").trim();

  try {
    // Kapso list often ignores/weakly applies `phone`; always filter client-side
    // (cross-customer quote bleed: Rinfor←Isbe←Así Es La Vida, 2026-07-18).
    const conversationsPayload = await kapsoGet(cfg, "/platform/v1/whatsapp/conversations", {
      phone: phoneDigits,
      q: phoneDigits,
      per_page: 20,
    });
    const conversationsRaw = unwrapList(conversationsPayload);
    const conversations = conversationsRaw.filter((c) =>
      conversationMatchesPhone(c, phoneDigits)
    );
    if (!conversations.length) {
      return {
        ok: false,
        error: conversationsRaw.length ? "no_conversations_for_phone" : "no_conversations",
        quote: null,
        funnel: null,
        order_focus: null,
        source: null,
      };
    }

    // Preferir hilos ended recientes, luego otros activos distintos al actual.
    const ordered = [...conversations].sort((a, b) => {
      const ta = Date.parse(a.last_active_at || a.updated_at || a.created_at || 0);
      const tb = Date.parse(b.last_active_at || b.updated_at || b.created_at || 0);
      return tb - ta;
    });

    let best = null;

    for (const conversation of ordered) {
      const conversationId = String(conversation.id || "");
      if (!conversationId) continue;

      const executionsPayload = await kapsoGet(
        cfg,
        `/platform/v1/workflows/${cfg.workflowId}/executions`,
        {
          whatsapp_conversation_id: conversationId,
          per_page: 5,
        }
      );
      // Platform a veces anida { executions: [...] } dentro de data.
      const executions = unwrapList(
        executionsPayload?.executions ? executionsPayload : executionsPayload
      );

      for (const execution of executions) {
        const executionId = String(execution.id || "");
        if (!executionId || executionId === currentExecutionId) continue;

        const detailPayload = await kapsoGet(
          cfg,
          `/platform/v1/workflow_executions/${executionId}`
        );
        const detail = detailPayload?.execution || detailPayload;
        const priorVars =
          detail?.execution_context?.vars ||
          detailPayload?.execution_context?.vars ||
          {};
        const rawQuote = priorVars.quote || null;
        if (!quoteLooksUseful(rawQuote)) continue;

        const quote = normalizeQuote({
          ...rawQuote,
          customer_display_name_explicit: Boolean(
            priorVars.quote?.customer_display_name_explicit
          ),
        });
        const candidate = {
          ok: true,
          error: null,
          quote,
          resume_hint: continuityResumeHint(quote),
          funnel: priorVars.funnel || null,
          order_focus: {
            id: priorVars.orders?.focus_order_id || priorVars.order?.id || null,
            name: priorVars.orders?.focus_order_name || priorVars.order?.name || null,
          },
          source: {
            conversation_id: conversationId,
            execution_id: executionId,
            status: detail?.status || execution.status || null,
            same_conversation: conversationId === currentConversationId,
          },
          _score: quoteRichnessScore(quote),
        };
        if (!best || candidate._score > best._score) best = candidate;
      }
    }

    if (best) {
      const { _score, ...rest } = best;
      return rest;
    }
  } catch (err) {
    return {
      ok: false,
      error: String(err?.message || err || "hydrate_failed").slice(0, 240),
      quote: null,
      funnel: null,
      order_focus: null,
      source: null,
    };
  }

  return {
    ok: false,
    error: "no_useful_quote",
    quote: null,
    funnel: null,
    order_focus: null,
    source: null,
  };
}

function mapActiveOrders(activeOrders = [], projectTasks = []) {
  const taskByOrderId = new Map();
  for (const task of projectTasks || []) {
    const soId = Array.isArray(task.sale_order_id)
      ? task.sale_order_id[0]
      : task.sale_order_id;
    if (!soId || taskByOrderId.has(soId)) continue;
    taskByOrderId.set(soId, {
      task_id: task.id,
      task_name: task.name || null,
      stage: Array.isArray(task.stage_id) ? task.stage_id[1] : null,
    });
  }

  return (activeOrders || []).map((order) => {
    const linked = taskByOrderId.get(order.id) || {};
    return {
      id: order.id,
      name: order.name,
      state: order.state,
      task_id: linked.task_id || null,
      task_stage: linked.stage || null,
    };
  });
}



async function fetchOpenOpportunityDossier(executeKw, partnerId) {
  if (!partnerId) return null;
  try {
    const leads = await executeKw(
      "crm.lead",
      "search_read",
      [
        [
          ["partner_id", "=", partnerId],
          ["type", "=", "opportunity"],
          ["active", "=", true],
        ],
      ],
      {
        fields: ["id", "name", "description", "stage_id", "write_date"],
        limit: 5,
        order: "write_date desc",
      }
    );
    for (const lead of leads || []) {
      const parsed = parseDossierFromDescription(lead.description || "");
      if (parsed && quoteLooksUseful(parsed)) {
        return {
          lead_id: lead.id,
          lead_name: lead.name || null,
          stage: Array.isArray(lead.stage_id) ? lead.stage_id[1] : null,
          quote: parsed,
        };
      }
    }
  } catch (_e) {
    return null;
  }
  return null;
}

async function handler(request, env) {
  const body = await request.json().catch(() => ({}));
  const vars = body?.execution_context || {};
  const execVars = vars.vars || body?.execution_context?.vars || {};
  const input = body?.input || {};
  const whatsappContext = body?.whatsapp_context || {};
  const now = new Date().toISOString();

  const phone = String(
    input.phone ||
      execVars?.user?.wa_id ||
      execVars?.user?.phone ||
      whatsappContext?.conversation?.phone_number ||
      ""
  ).trim();
  const currentConversationId = String(
    whatsappContext?.conversation?.id || execVars?.kapso?.conversation_id || ""
  ).trim();
  const currentExecutionId = String(
    body?.execution_id ||
      body?.workflow_execution_id ||
      execVars?.kapso?.execution_id ||
      ""
  ).trim();

  const ODOO_URL = env.ODOO_URL;
  const ODOO_DB = env.ODOO_DB;
  const ODOO_USERNAME = env.ODOO_USERNAME;
  const ODOO_PASSWORD = env.ODOO_PASSWORD;
  const stakeholders = String(env.LIFE_STAKEHOLDER_WHITELIST || "")
    .split(",")
    .map((v) => v.trim())
    .filter(Boolean);

  const normalizedPhone = normalizeWaPhone(phone);
  const baseUser = execVars?.user || {};
  if (!normalizedPhone.e164Digits) {
    return response("new_customer", false, 0, now, baseUser);
  }
  if (
    stakeholders.includes(normalizedPhone.e164Digits) ||
    stakeholders.includes(normalizedPhone.e164Plus)
  ) {
    return response("stakeholder", true, 0, now, baseUser);
  }

  // Memoria Kapso: retomar quote aunque Odoo no conozca al partner aún.
  const hydrateResult = await hydrateCustomerSessionFromKapso(env, phone, {
    currentConversationId,
    currentExecutionId,
  });
  const hydrated =
    hydrateResult?.ok && hydrateResult?.quote ? hydrateResult : null;
  const hydrateError = hydrateResult?.ok ? null : hydrateResult?.error || null;
  const existingQuote = execVars?.quote || null;

  if (!ODOO_URL || !ODOO_DB || !ODOO_USERNAME || !ODOO_PASSWORD) {
    return response("new_customer", false, 0, now, baseUser, null, {
      hydrated,
      hydrateError,
      existingQuote,
      activeOrders: [],
      projectTasks: [],
      lastOrder: null,
      historyCount: 0,
    });
  }

  try {
    const rpc = async (service, method, args) => {
      const resp = await fetch(`${ODOO_URL}/jsonrpc`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          jsonrpc: "2.0",
          method: "call",
          params: { service, method, args },
        }),
      });
      const json = await resp.json();
      if (json?.error) throw new Error(json.error?.message || "Odoo RPC error");
      return json.result;
    };
    const uid = await rpc("common", "authenticate", [
      ODOO_DB,
      ODOO_USERNAME,
      ODOO_PASSWORD,
      {},
    ]);
    if (!uid) {
      return response("new_customer", false, 0, now, baseUser, null, {
        hydrated,
        hydrateError,
        existingQuote,
        activeOrders: [],
        projectTasks: [],
        lastOrder: null,
        historyCount: 0,
      });
    }

    const executeKw = async (model, method, positionalArgs = [], kw = {}) =>
      rpc("object", "execute_kw", [
        ODOO_DB,
        uid,
        ODOO_PASSWORD,
        model,
        method,
        positionalArgs,
        kw,
      ]);

    const lookup = await findPartnerByWaPhone(executeKw, phone, {
      fields: ["id", "name", "phone", "phone_sanitized"],
    });
    const partner = lookup.partner;
    if (!partner?.id) {
      return response("new_customer", false, 0, now, baseUser, null, {
        hydrated,
        hydrateError,
        existingQuote,
        activeOrders: [],
        projectTasks: [],
        lastOrder: null,
        historyCount: 0,
      });
    }

    const orders = await executeKw(
      "sale.order",
      "search_read",
      [[["partner_id", "=", partner.id]]],
      {
        fields: ["id", "name", "state", "date_order"],
        limit: 10,
        order: "id desc",
      }
    );
    const historyCount = Array.isArray(orders) ? orders.length : 0;
    const lastOrder = historyCount ? orders[0] : null;

    let activeOrders = [];
    try {
      activeOrders = await executeKw(
        "sale.order",
        "search_read",
        [
          [
            ["partner_id", "=", partner.id],
            ["state", "in", ["draft", "sent", "sale"]],
          ],
        ],
        { fields: ["id", "name", "state"], limit: 8, order: "id desc" }
      );
    } catch (_e) {
      activeOrders = [];
    }

    let projectTasks = [];
    try {
      projectTasks = await executeKw(
        "project.task",
        "search_read",
        [[["partner_id", "=", partner.id]]],
        {
          fields: ["id", "name", "stage_id", "project_id", "sale_order_id"],
          limit: 8,
          order: "write_date desc",
        }
      );
    } catch (_e) {
      const orderIds = (orders || []).map((o) => o.id);
      if (orderIds.length) {
        try {
          projectTasks = await executeKw(
            "project.task",
            "search_read",
            [[["sale_order_id", "in", orderIds]]],
            {
              fields: ["id", "name", "stage_id", "project_id", "sale_order_id"],
              limit: 8,
              order: "write_date desc",
            }
          );
        } catch (_e2) {
          projectTasks = [];
        }
      }
    }

    const activeOrderCount = Array.isArray(activeOrders) ? activeOrders.length : 0;
    const projectCardCount = Array.isArray(projectTasks) ? projectTasks.length : 0;
    const latestTask = projectCardCount ? projectTasks[0] : null;
    const hasHistoryOrActive =
      historyCount > 0 || activeOrderCount > 0 || projectCardCount > 0;

    const opportunityDossier = await fetchOpenOpportunityDossier(
      executeKw,
      partner.id
    );

    const partnerUserFields = {
      partner_id: partner.id,
      partner_name: partner.name || null,
      partner_match_strategy: lookup.match_strategy,
      partner_match_ambiguous: lookup.ambiguous,
      partner_match_candidates: lookup.candidates || [],
      wa_phone_normalized: normalizedPhone.e164Plus,
    };

    const segment = hasHistoryOrActive ? "existing_customer" : "new_customer";
    return response(segment, true, historyCount, now, {
      ...baseUser,
      ...partnerUserFields,
      has_active_orders: activeOrderCount > 0,
      has_project_cards: projectCardCount > 0,
    }, null, {
      hydrated,
      hydrateError,
      opportunityDossier,
      activeOrders,
      projectTasks,
      lastOrder,
      historyCount,
      latestTask,
      projectCardCount,
      existingQuote,
    });
  } catch (_error) {
    return response("new_customer", false, 0, now, baseUser, "odoo_error", {
      hydrated,
      hydrateError,
      existingQuote,
      activeOrders: [],
      projectTasks: [],
      lastOrder: null,
      historyCount: 0,
    });
  }
}

function response(
  segment,
  known,
  historyCount,
  now,
  baseUser = {},
  errorCode = null,
  extras = {}
) {
  const activeMapped = mapActiveOrders(
    extras.activeOrders || [],
    extras.projectTasks || []
  );
  const hydrated = extras.hydrated || null;
  const opportunityDossier = extras.opportunityDossier || null;
  const lastOrder = extras.lastOrder || null;
  const latestTask = extras.latestTask || null;
  const projectCardCount = Number(extras.projectCardCount || 0);

  // Memoria: Kapso hydrate + dossier CRM (elige/merge el más rico)
  let resumedQuote = null;
  let continuitySource = known ? "odoo_only" : "none";
  let continuityMeta = {
    conversation_id: null,
    execution_id: null,
    prior_status: null,
    same_conversation: null,
    opportunity_id: null,
  };

  if (hydrated?.quote) {
    resumedQuote = normalizeQuote(hydrated.quote);
    continuitySource = "kapso_prior_execution";
    continuityMeta = {
      conversation_id: hydrated.source?.conversation_id || null,
      execution_id: hydrated.source?.execution_id || null,
      prior_status: hydrated.source?.status || null,
      same_conversation: hydrated.source?.same_conversation ?? null,
      opportunity_id: null,
    };
  }
  if (opportunityDossier?.quote) {
    const crmQuote = normalizeQuote(opportunityDossier.quote);
    if (!resumedQuote) {
      resumedQuote = crmQuote;
      continuitySource = "odoo_crm_dossier";
      continuityMeta.opportunity_id = opportunityDossier.lead_id || null;
    } else {
      const merged = mergeQuotes(resumedQuote, crmQuote, { bumpRevision: false });
      // Preferir CRM si es más rico (sobrevive semanas)
      resumedQuote =
        quoteRichnessScore(crmQuote) >= quoteRichnessScore(resumedQuote)
          ? mergeQuotes(resumedQuote, crmQuote, { bumpRevision: false })
          : merged;
      continuitySource = "kapso_and_crm_dossier";
      continuityMeta.opportunity_id = opportunityDossier.lead_id || null;
    }
  }

  const outVars = {
    user: {
      ...baseUser,
      contact_segment: segment,
      is_known_in_odoo: known,
      history_count: historyCount,
    },
    orders: {
      active: activeMapped,
      active_count: activeMapped.length,
      focus_order_id:
        activeMapped.length === 1
          ? activeMapped[0].id
          : hydrated?.order_focus?.id || null,
      focus_order_name:
        activeMapped.length === 1
          ? activeMapped[0].name
          : hydrated?.order_focus?.name || null,
    },
    session: {
      continuity: resumedQuote
        ? {
            resumed: true,
            source: continuitySource,
            conversation_id: continuityMeta.conversation_id,
            execution_id: continuityMeta.execution_id,
            prior_status: continuityMeta.prior_status,
            same_conversation: continuityMeta.same_conversation,
            opportunity_id: continuityMeta.opportunity_id,
            resume_hint: continuityResumeHint(resumedQuote),
            resumed_at: now,
          }
        : {
            resumed: false,
            source: known ? "odoo_only" : "none",
            hydrate_error: extras.hydrateError || null,
            resumed_at: now,
          },
    },
    service: {
      last_call_name: "classify_contact_odoo",
      last_call_status: errorCode ? "fallback" : "ready",
      last_call_at: now,
      fallback_message: errorCode,
    },
  };

  if (lastOrder || hydrated?.order_focus?.id) {
    outVars.order = {
      last_order_id: lastOrder?.id || null,
      last_order_name: lastOrder?.name || null,
      last_order_state: lastOrder?.state || null,
      id: hydrated?.order_focus?.id || null,
      name: hydrated?.order_focus?.name || null,
    };
  }

  if (projectCardCount || latestTask) {
    outVars.project = {
      active_card_count: projectCardCount,
      latest_card_name: latestTask?.name || null,
      latest_stage: Array.isArray(latestTask?.stage_id)
        ? latestTask.stage_id[1]
        : null,
      latest_project_name: Array.isArray(latestTask?.project_id)
        ? latestTask.project_id[1]
        : null,
    };
  }

  if (opportunityDossier?.lead_id) {
    outVars.crm = {
      opportunity_id: opportunityDossier.lead_id,
      opportunity_name: opportunityDossier.lead_name || null,
      opportunity_stage: opportunityDossier.stage || null,
    };
  }

  // Solo rehidratar quote si la ejecución actual aún no tiene uno útil.
  const currentQuote = extras.existingQuote || null;
  const hasCurrentQuote = quoteLooksUseful(currentQuote);
  if (resumedQuote && !hasCurrentQuote) {
    outVars.quote = resumedQuote;
  } else if (resumedQuote && hasCurrentQuote) {
    outVars.quote = mergeQuotes(resumedQuote, currentQuote, { bumpRevision: false });
  }
  if (hydrated?.funnel) {
    outVars.funnel = hydrated.funnel;
  }

  return new Response(
    JSON.stringify({
      vars: outVars,
      status: "ready",
      message: resumedQuote
        ? "Contacto clasificado; sesión comercial retomada (Kapso/CRM dossier)."
        : "Contacto clasificado por telefono contra Odoo.",
    }),
    { headers: { "Content-Type": "application/json" } }
  );
}

{ handler };

