// ===== registrar-adjuntos-pedido (9f144024-859a-4c21-bc83-7acad5893489) =====
/**
 * Utilidades compartidas — parse lista pedido staff (tools internas agente).
 */

const FIXED_IMAGE_LIST_QUESTION =
  "Extrae SOLO un JSON array de objetos con keys: numero, nombre, talla, manga, genero (masculino|femenino), arquero (true|false). Sin markdown ni texto extra.";

function compact(value) {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

function digitsOnly(value) {
  return String(value ?? "").replace(/\D/g, "");
}

function normalizeBoolean(value) {
  const text = compact(value).toLowerCase();
  return ["1", "true", "si", "sí", "x", "ok", "yes"].includes(text);
}

/** Marca de casilla Excel (X). Texto libre en la celda no cuenta como marca. */
function isCheckboxMarkValue(value) {
  const t = compact(value).toUpperCase();
  if (!t) return false;
  if (/^\d{2,}$/.test(t)) return false;
  return t === "X" || t === "SI" || t === "SÍ" || t === "1" || t === "TRUE";
}

/** Texto en celda de producto (Camiseta/Uniforme) que no es casilla X. */
function cellInlineNote(value) {
  const t = compact(value);
  if (!t || isCheckboxMarkValue(t)) return "";
  return t;
}

/** Solo pantaloneta / short — no camiseta ni uniforme completo. */
function isPantalonetaOnlyText(...parts) {
  const joined = parts.filter(Boolean).map(compact).join(" ").toLowerCase();
  if (!joined) return false;
  if (
    /solo\s*pantalon|s[oó]lo\s*pantalon|pantaloneta\s*sol|sol[oa]\s+pantaloneta|solo\s+pantaloneta/.test(
      joined
    )
  ) {
    return true;
  }
  if (/\bpantaloneta\b/.test(joined) && /\b(solo|sólo|solamente)\b/.test(joined)) return true;
  return false;
}

function inferAttachmentRole(filename, mimeType = "") {
  const name = compact(filename).toLowerCase();
  const mime = compact(mimeType).toLowerCase();

  if (/\.(xlsx|xlsm|xltx|xls|csv)$/i.test(name) || mime.includes("spreadsheet") || mime.includes("excel")) {
    return "detail_list";
  }
  if (/\.docx$/i.test(name) || mime.includes("wordprocessingml")) {
    return "detail_list";
  }
  if (
    /lista|tallas|formato|pedido|nomin|jugador|alumno|roster|plantel/i.test(name) &&
    /\.(jpe?g|png|webp|pdf)$/i.test(name)
  ) {
    return "detail_list";
  }
  if (/referencia|diseno|diseño|mockup|logo|arte|wildcat|hub/i.test(name)) {
    return "design_reference";
  }
  if (/\.(jpe?g|png|webp|gif)$/i.test(name) || mime.startsWith("image/")) {
    return "design_reference";
  }
  if (/\.pdf$/i.test(name) || mime === "application/pdf") {
    return "detail_list";
  }
  return "other";
}

function pickMediaFromContext(body) {
  const input = body?.input || body?.data || {};
  const vars = body?.execution_context?.vars || {};
  const ctx = body?.whatsapp_context || {};
  const messages = Array.isArray(ctx.messages) ? ctx.messages : [];

  const inbound = [...messages].reverse().filter((m) => m.direction === "inbound");
  const mediaFromMessages = [];
  for (const msg of inbound.slice(0, 12)) {
    const url =
      msg?.media_url ||
      msg?.media?.url ||
      msg?.document?.url ||
      msg?.image?.url ||
      null;
    if (!url || !String(url).startsWith("http")) continue;
    const filename =
      compact(msg?.media?.filename || msg?.document?.filename || msg?.filename) ||
      filenameFromUrl(url);
    const mime = compact(msg?.media?.mime_type || msg?.mimetype || "");
    mediaFromMessages.push({ url, filename, mime_type: mime, role: inferAttachmentRole(filename, mime) });
  }

  const candidates = [
    input.file_url,
    input.media_url,
    input.url,
    vars?.media?.source_url,
    vars?.media?.url,
    ctx?.media_data?.url,
    ctx?.last_media_url,
  ];

  let primaryUrl = null;
  for (const c of candidates) {
    const url = compact(c);
    if (url.startsWith("http")) {
      primaryUrl = url;
      break;
    }
  }

  if (primaryUrl && !mediaFromMessages.some((m) => m.url === primaryUrl)) {
    const filename = compact(input.filename) || filenameFromUrl(primaryUrl);
    const mime = compact(input.mime_type || ctx?.media_data?.mime_type || "");
    mediaFromMessages.unshift({
      url: primaryUrl,
      filename,
      mime_type: mime,
      role: inferAttachmentRole(filename, mime),
    });
  }

  return { primaryUrl, mediaFromMessages };
}

function filenameFromUrl(fileUrl) {
  try {
    const base = new URL(fileUrl).pathname.split("/").pop();
    return base ? decodeURIComponent(base) : "archivo";
  } catch {
    return "archivo";
  }
}

/**
 * Fila canónica para order_draft.detail.rows (compatible build_odoo_order_note).
 */
function toDetailRow(raw) {
  if (!raw || typeof raw !== "object") return null;

  const numero = compact(raw.numero || raw.number || raw.dorsal || raw.n);
  const arqueroFromRaw =
    normalizeBoolean(raw.arquero || raw.ARQUERO) ||
    (!raw.pantaloneta && /arquer|porter/i.test(compact(raw.rol || raw.comentario || "")));

  let nombre = compact(raw.nombre || raw.name || raw.nombre_uniforme);
  const tallaEarly = compact(raw.talla || raw.size || raw.TALLA);
  const isUniformeRow =
    !normalizeBoolean(raw.pantaloneta) &&
    !normalizeBoolean(raw.camiseta) &&
    (normalizeBoolean(raw.uniforme) || raw.uniforme !== false);
  const intentionalBlankName = normalizeBoolean(raw.nombre_vacio_impresion);

  if (!nombre && arqueroFromRaw && numero) nombre = `Arquero #${numero}`;
  if (!nombre && arqueroFromRaw) nombre = "Arquero";
  if (!nombre && numero && normalizeBoolean(raw.camiseta)) nombre = `Camiseta #${numero}`;
  if (!nombre && intentionalBlankName && isUniformeRow && (numero || tallaEarly)) {
    nombre = "";
  }
  if (!nombre && !numero && !tallaEarly) return null;

  const talla = compact(raw.talla || raw.size || raw.TALLA);
  const manga = compact(raw.manga || raw.sleeve || raw["Larga/Corta"] || raw.manga_variante);

  let grupo = compact(raw.grupo || raw.genero || raw.gender || raw.GENERO).toLowerCase();
  if (/fem|mujer/.test(grupo)) grupo = "femenino";
  else if (/masc|hombre|varon/.test(grupo)) grupo = "masculino";
  else if (!grupo && normalizeBoolean(raw.fem || raw.FEM)) grupo = "femenino";
  else if (!grupo && normalizeBoolean(raw.mas || raw.MAS)) grupo = "masculino";
  else if (!grupo) grupo = "general";

  const comentario = compact(raw.comentario || "");
  const pantaloneta =
    normalizeBoolean(raw.pantaloneta) ||
    isPantalonetaOnlyText(comentario, raw.rol, raw.nota_celda);

  let rol = compact(
    raw.rol || raw.role || raw.variante || raw.curso_equipo || raw.equipo || raw.grupo_detalle
  );
  if (pantaloneta) {
    const notes = comentario
      .split(" · ")
      .map((s) => s.trim())
      .filter((s) => s && !/^solo\s*pantaloneta$/i.test(s));
    const unique = [...new Set(notes)];
    rol = unique.length ? `Pantaloneta · ${unique.join(" · ")}` : "Pantaloneta";
  } else if (!rol) {
    const parts = [];
    if (normalizeBoolean(raw.camiseta)) parts.push("Camiseta");
    else if (normalizeBoolean(raw.uniforme) || raw.uniforme === undefined) {
      if (raw.uniforme !== false) parts.push("Uniforme");
    }
    if (comentario) parts.push(comentario);
    rol = parts.join(" · ");
  } else if (comentario && !rol.includes(comentario)) {
    rol = `${rol} · ${comentario}`;
  }

  const arquero =
    !pantaloneta && (arqueroFromRaw || /arquer|porter/i.test(rol));

  return {
    person_id: compact(raw.person_id || raw.personId || "") || null,
    numero: numero || "",
    nombre,
    talla: talla || "",
    grupo,
    rol: rol || "",
    manga: manga || "",
    arquero,
    camiseta: pantaloneta ? false : normalizeBoolean(raw.camiseta),
    uniforme: pantaloneta ? false : raw.uniforme !== false && !normalizeBoolean(raw.camiseta),
    pantaloneta,
    comentario,
    nombre_vacio_impresion: intentionalBlankName && !nombre,
    impresion_delantera: compact(raw.impresion_delantera || "") || null,
    impresion_trasera: compact(raw.impresion_trasera || "") || null,
    product_line_key: compact(raw.product_line_key || raw.section_key || "") || null,
    product_text: compact(raw.product_text || "") || null,
    garment_type: compact(raw.garment_type || "") || null,
    category: compact(raw.category || "") || null,
    variant_notes: compact(raw.variant_notes || "") || null,
  };
}

function componentTypeFromRow(row) {
  if (row.pantaloneta) return "pantaloneta";
  if (row.camiseta) return "camiseta";
  if (row.uniforme) return "uniforme_completo";
  return row.garment_type || "prenda";
}

function detailRowsToPeople(rows) {
  const people = [];
  const byId = new Map();
  (Array.isArray(rows) ? rows : []).forEach((raw, index) => {
    const row = toDetailRow(raw);
    if (!row) return;
    const personId = row.person_id || `row-${index + 1}`;
    let person = byId.get(personId);
    if (!person) {
      person = {
        person_id: personId,
        identity: {
          display_name: row.nombre || null,
          print_name: row.nombre || null,
          number: row.numero || null,
          group: row.grupo || "general",
        },
        components: [],
        comments: [],
      };
      byId.set(personId, person);
      people.push(person);
    }
    person.components.push({
      type: componentTypeFromRow(row),
      size: row.talla || null,
      sleeve: row.manga || null,
      goalkeeper: Boolean(row.arquero),
      product_line_key: row.product_line_key,
      product_text: row.product_text,
      garment_type: row.garment_type,
      category: row.category,
      variant_notes: row.variant_notes,
      printing: {
        front: row.impresion_delantera,
        back: row.impresion_trasera,
      },
      comment: row.comentario || null,
    });
    if (row.comentario && !person.comments.includes(row.comentario)) {
      person.comments.push(row.comentario);
    }
  });
  return people;
}

function peopleToDetailRows(people) {
  const rows = [];
  for (const person of Array.isArray(people) ? people : []) {
    const identity = person?.identity || {};
    const components = Array.isArray(person?.components) ? person.components : [];
    for (const component of components) {
      const type = compact(component?.type).toLowerCase();
      rows.push(
        toDetailRow({
          person_id: compact(person.person_id) || null,
          nombre: identity.print_name ?? identity.display_name,
          numero: identity.number,
          genero: identity.group,
          talla: component?.size,
          manga: component?.sleeve,
          arquero: component?.goalkeeper,
          camiseta: type === "camiseta" || type === "camiseta_sola",
          uniforme: type === "uniforme" || type === "uniforme_completo",
          pantaloneta: type === "pantaloneta",
          comentario: component?.comment || (person.comments || []).join(" · "),
          impresion_delantera: component?.printing?.front,
          impresion_trasera: component?.printing?.back,
          product_line_key: component?.product_line_key,
          product_text: component?.product_text,
          garment_type: component?.garment_type || type,
          category: component?.category,
          variant_notes: component?.variant_notes,
        })
      );
    }
  }
  return rows.filter(Boolean);
}

function buildDetailSummary(rows) {
  if (!Array.isArray(rows) || !rows.length) {
    return "Sin filas de lista parseadas.";
  }
  const masc = rows.filter((r) => r.grupo === "masculino").length;
  const fem = rows.filter((r) => r.grupo === "femenino").length;
  const general = rows.length - masc - fem;
  const parts = [`${rows.length} filas`];
  if (masc) parts.push(`${masc} M`);
  if (fem) parts.push(`${fem} F`);
  if (general) parts.push(`${general} general`);
  const missingTalla = rows.filter((r) => !r.talla).length;
  const missingNum = rows.filter((r) => !r.numero).length;
  if (missingTalla) parts.push(`${missingTalla} sin talla`);
  if (missingNum) parts.push(`${missingNum} sin número`);
  return parts.join(" · ");
}

function mergeAttachments(existing, incoming) {
  const out = Array.isArray(existing) ? [...existing] : [];
  const seen = new Set(out.map((a) => `${a.url}|${a.filename}`));
  for (const att of incoming || []) {
    const url = compact(att?.url);
    if (!url.startsWith("http")) continue;
    const key = `${url}|${compact(att.filename)}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({
      url,
      filename: compact(att.filename) || filenameFromUrl(url),
      mime_type: compact(att.mime_type) || null,
      role: att.role || inferAttachmentRole(att.filename, att.mime_type),
    });
  }
  return out;
}

function mergeDetailRows(existing, incoming, mode = "replace") {
  const oldRows = Array.isArray(existing) ? existing.map(toDetailRow).filter(Boolean) : [];
  const newRows = Array.isArray(incoming) ? incoming.map(toDetailRow).filter(Boolean) : [];
  if (mode === "append") {
    const key = (r) => `${r.numero}|${r.nombre}|${r.talla}`.toLowerCase();
    const seen = new Set(oldRows.map(key));
    const merged = [...oldRows];
    for (const row of newRows) {
      const k = key(row);
      if (seen.has(k)) continue;
      seen.add(k);
      merged.push(row);
    }
    return merged;
  }
  return newRows.length ? newRows : oldRows;
}

function buildWarnings(rows) {
  const warnings = [];
  if (!rows.length) warnings.push("No hay filas en la lista.");
  rows.forEach((row, idx) => {
    if (!row.talla) warnings.push(`Fila ${idx + 1} (${row.nombre}): sin talla`);
    if (!row.numero) warnings.push(`Fila ${idx + 1} (${row.nombre}): sin número`);
  });
  return warnings;
}

function parseStatusFrom(rows, warnings) {
  if (!rows.length) return "needs_review";
  const critical = warnings.some((w) => /sin talla|sin número|No hay filas/i.test(w));
  if (critical && rows.length < 3) return "needs_review";
  if (warnings.length) return "partial";
  return "ok";
}

function patchOrderDraft(vars, patch) {
  const prev = vars?.order_draft || {};
  const detail = { ...(prev.detail || {}), ...(patch.detail || {}) };
  if (patch.detail?.rows) detail.rows = patch.detail.rows;
  return {
    ...prev,
    ...patch,
    detail,
    attachments: patch.attachments ?? prev.attachments ?? [],
    blockers: patch.blockers ?? prev.blockers ?? [],
  };
}

function serviceVars(name, status, now, fallback = null) {
  return {
    service: {
      last_call_name: name,
      last_call_status: status,
      last_call_at: now,
      fallback_message: fallback,
    },
  };
}

function jsonResponse(payload, status = 200) {
  return new Response(JSON.stringify(payload), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

async function fetchBinary(fileUrl) {
  const resp = await fetch(fileUrl);
  if (!resp.ok) throw new Error(`download_failed:${resp.status}`);
  return new Uint8Array(await resp.arrayBuffer());
}


/**
 * Kapso tool: registrar-adjuntos-pedido
 */
async function handler(request, env) {
  const body = await request.json().catch(() => ({}));
  const input = body?.input || {};
  const vars = body?.execution_context?.vars || {};
  const now = new Date().toISOString();

  if (vars?.user?.role !== "staff") {
    return jsonResponse({ ok: false, error: "staff_only" }, 403);
  }

  const { mediaFromMessages } = pickMediaFromContext(body);
  const manual = Array.isArray(input.attachments) ? input.attachments : [];
  const attachments = mergeAttachments(vars?.order_draft?.attachments, [
    ...mediaFromMessages,
    ...manual,
  ]);

  const order_draft = patchOrderDraft(vars, { attachments });

  return jsonResponse({
    ok: true,
    attachment_count: attachments.length,
    attachments,
    vars: {
      order_draft,
      ...serviceVars("registrar_adjuntos_pedido", "ready", now, null),
    },
  });
}

// ===== route-customer-burst-resume (972d60bb-ff84-40fc-ba3d-cdd6104aa143) =====
/**
 * route_customer_burst_resume — tras wait_customer_burst (debounce ~30s).
 * timeout / silencio → vendedor; user_input → reinicia el wait;
 * ignore → vuelve al wait sin responder (prefill Meta Ads solo, o spam).
 *
 * Prioridad: ventas legítimas (keywords / audio con contenido comercial) siempre
 * van a vendedor. Prefill "Hola, quiero cotizar uniformes de" solo → ignore.
 */
async function handler(request, env) {
  const body = await request.json().catch(() => ({}));
  const availableEdges = Array.isArray(body?.available_edges) ? body.available_edges : [];
  const executionContext = body?.execution_context || {};
  const vars = executionContext.vars || {};
  const system = executionContext.system || body?.system || {};
  const whatsappContext = body?.whatsapp_context || {};
  const messages = Array.isArray(whatsappContext.messages) ? whatsappContext.messages : [];
  const conversation = whatsappContext.conversation || {};
  const now = new Date().toISOString();

  const BLACKLIST = [
    "3000000035", // Johanna Castellanos
    "3000000062", // Stephany
    "3000000030", // Maria-Luci
    "3000000027", // Que Dios Me Mendiga
    "3000000079", // Kris💜💜
    "3000000063", // Alba Estrada
    "3000000007", // mangonesjoao
    "584226400323", // Yaneida
    "3000000078", // Luis angel Marin
    "3000000017", // Victoria junco
    "3000000038", // Bertha Hernández
    "3000000033", // Te Amo Hija Mía Celeste
    "3000000071", // Michell Girón
    "3000000050", // Yofe
    "3000000044", // Karen Ojeda
    "3000000049",
    "3000000083", // Michel (insultos)
    "3000000012",
    "3000000072",
    "3000000037", // Deymar Y Emma
    "3000000075", // Isaac David
    "3000000005",
    "3000000074",
    "584260851544", // Rosales
    "3000000036", // AE
    "3000000077", // LOA
    "3000000057", // Valledupar
    "3000000065", // gonzalesberriosanapaola
    "3000000026", // cristian
    "3000000073", // Carolina Acosta / Michell
    "3000000015",
    "3000000011", // Sergio
    "3000000076", // Wendy Perez
    "3000000010",
    "3000000003", // spam 2026-07-15 (😍❤️) gibberish + sticker
    "3000000041", // spam 2026-07-15 (anarincon819) pocket dial / child play
  ];

  const GENUINE_KEYWORDS = [
    "uniforme", "camiseta", "buzo", "pantaloneta", "medias", "talla", "futbol",
    "precio", "cotizar", "voley", "voleibol", "baloncesto", "arquero", "diseno", "sublimado",
    "dorsal", "nombre", "estampado", "taller", "pedido", "compra", "cotizacion",
    "presupuesto", "prenda", "tela", "dumonti", "dry", "manga", "cuello", "saco",
    "chaqueta", "pantalon", "licra", "impermeable", "bolsillo", "bordado",
    "vendedor", "asesor", "persona", "atencion", "humano", "atender", "cantidad",
    "unidad", "unidades", "equipo", "club", "colegio",
  ];

  const NON_VERBAL_MARKERS = [
    "silence", "ruido", "background noise", "outro jingle", "pause", "screaming",
    "sniffs", "sliding", "clicking", "musica", "music", "beeping", "throat",
    "inhales", "rain", "background", "noise", "jingle", "crying", "mooing",
    "rustling", "babbling", "paper", "laughter", "laugh", "cough", "sneeze",
    "breathing", "static", "humming", "whistle", "animal", "meow", "bark",
  ];

  const COLOMBIAN_INSULTS = [
    /\bmalparid[oa]/i,
    /\bsapo\b/i,
    /\b(gonorrea|hpta|mierda|hp)\b/i,
    /\bcoma\s+mierda/i,
    /\bhijo\s+de\s+puta/i,
    /\bcarechimba/i,
  ];

  const GREETING_ONLY = /^(hola+|buenas?|buenos\s+dias?|buenas\s+tardes?|buenas\s+noches?|hi|hey|ok|oki|si|sí|dale|ya)$/i;

  const context = executionContext.context || body?.context || {};
  const waId = String(
    context?.phone_number ||
      conversation.phone_number ||
      vars?.user?.wa_id ||
      (messages[0] ? messages[0].from || messages[0].sender_phone_number : "") ||
      ""
  ).replace(/\D/g, "");

  function fold(s) {
    return String(s || "")
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "");
  }

  function getMessageText(msg) {
    if (!msg || typeof msg !== "object") return "";
    const direct = msg.content ?? msg.body;
    if (typeof direct === "string" && direct.trim()) return direct.trim();
    const nested = msg.text;
    if (typeof nested === "string" && nested.trim()) return nested.trim();
    if (nested && typeof nested === "object") {
      const bodyText = nested.body ?? nested.text;
      if (typeof bodyText === "string" && bodyText.trim()) return bodyText.trim();
    }
    return "";
  }

  function transcriptRawToString(raw) {
    if (!raw) return "";
    if (typeof raw === "string") return raw.trim();
    if (typeof raw === "object") {
      const t = raw.text ?? raw.transcript ?? raw.body ?? "";
      return typeof t === "string" ? t.trim() : "";
    }
    return "";
  }

  function getTranscript(msg) {
    if (!msg || typeof msg !== "object") return "";
    const fromFields = transcriptRawToString(
      msg.transcript ?? msg.metadata?.transcript ?? msg.kapso?.transcript
    );
    if (fromFields) return fromFields;
    // Kapso a veces embebe "Transcript: ..." en el body del audio
    const body = getMessageText(msg);
    const m = body.match(/transcript\s*:\s*(.+)$/is);
    if (m && m[1]) return m[1].trim();
    return "";
  }

  /**
   * Clasifica transcripción de audio:
   * - real_speech: habla humana con palabras → siempre contar (venta o no)
   * - non_verbal: silencio / ruido / animal / jingle
   * - empty: sin transcript
   */
  function classifyTranscript(rawText) {
    const original = String(rawText || "").trim();
    if (!original) return { kind: "empty", text: "", folded: "" };

    let folded = fold(original).replace(/\[|\]/g, " ");
    for (const mk of NON_VERBAL_MARKERS) {
      folded = folded.split(mk).join(" ");
    }
    folded = folded.replace(/[^a-z0-9ñ\s]/g, " ").replace(/\s+/g, " ").trim();

    const words = folded.split(/\s+/).filter((w) => w.length >= 2);
    const letters = (folded.match(/[a-zñ]/g) || []).length;

    if (words.length >= 3 && letters >= 12) {
      return { kind: "real_speech", text: original, folded };
    }
    if (words.length >= 2 && letters >= 16) {
      return { kind: "real_speech", text: original, folded };
    }
    return { kind: "non_verbal", text: original, folded };
  }

  /** Prefill Meta Ads click-to-WhatsApp (sin deporte / sin pedido real). */
  function isAdsPrefillGreeting(text) {
    const t = fold(text).replace(/\s+/g, " ").trim();
    if (!t) return false;
    return (
      /^hola,?\s*quiero\s+cotizar\s+uniformes\s+de\s*$/.test(t) ||
      /^hola,?\s*quiero\s+cotizar\s+uniformes\s*$/.test(t)
    );
  }

  function isKeyboardSmash(text) {
    const t = String(text || "").replace(/\s+/g, " ").trim();
    if (t.length < 36) return false;
    if (isAdsPrefillGreeting(t)) return false;
    const folded = fold(t);
    if (GENUINE_KEYWORDS.some((kw) => folded.includes(kw))) return false;
    const tokens = folded.split(/\s+/).filter(Boolean);
    if (tokens.length < 6) return false;
    const shortTok = tokens.filter((x) => x.length <= 3).length;
    const weirdTok = tokens.filter((x) => /[0-9]/.test(x) || /(.)\1{2,}/.test(x) || x.length <= 2).length;
    if (shortTok / tokens.length >= 0.4 && weirdTok / tokens.length >= 0.35) return true;
    if (/(.)\1{4,}/.test(folded)) return true;
    return false;
  }

  const inboundMessages = messages.filter((m) => m.direction === "inbound");

  const assignee = conversation.assignee || vars.assignee || vars.assignee_id || null;
  const hasHumanAssignee =
    assignee !== null &&
    assignee !== undefined &&
    String(assignee).toLowerCase() !== "null" &&
    String(assignee).trim() !== "";

  let allWordsCombined = "";
  let nonPrefillTextCount = 0;
  let prefillOnlyTexts = 0;
  let anyNonPrefillSignal = false;
  let realSpeechCount = 0;

  inboundMessages.forEach((m) => {
    const text = getMessageText(m);
    const transcript = getTranscript(m);
    const type = String(m.message_type || m.type || "").toLowerCase();
    const classified = classifyTranscript(transcript);

    if (text) {
      if (isAdsPrefillGreeting(text)) {
        prefillOnlyTexts++;
      } else {
        nonPrefillTextCount++;
        anyNonPrefillSignal = true;
        allWordsCombined += " " + fold(text);
      }
    }
    if (classified.kind === "real_speech") {
      realSpeechCount++;
      anyNonPrefillSignal = true;
      allWordsCombined += " " + classified.folded;
    }
    if (type === "image" || type === "video" || type === "document") {
      anyNonPrefillSignal = true;
    }
  });

  const hasGenuineKeyword = GENUINE_KEYWORDS.some((kw) => allWordsCombined.includes(kw));
  // Habla real en audio (aunque no diga "uniforme") cuenta como lead legítimo
  const hasRealSpeech = realSpeechCount >= 1;

  let isSpam = false;
  let spamReason = "";
  let isPrefillOnly = false;

  if (hasHumanAssignee) {
    isSpam = false;
  } else if (hasGenuineKeyword || hasRealSpeech) {
    // Prioridad ventas: keyword comercial O transcripción con habla real → nunca spam
    isSpam = false;
  } else {
    let audiosCount = 0;
    let imagesCount = 0;
    let stickersCount = 0;
    let shortTextsCount = 0;
    let nonSpamTextsCount = 0;
    let smashTextsCount = 0;
    const inboundTexts = [];
    const audioClassifications = [];

    inboundMessages.forEach((m) => {
      const type = String(m.message_type || m.type || "").toLowerCase();
      const textBody = getMessageText(m);

      if (type === "audio") {
        audiosCount++;
        audioClassifications.push(classifyTranscript(getTranscript(m)));
      } else if (type === "image" || type === "video") {
        imagesCount++;
      } else if (type === "sticker") {
        stickersCount++;
      } else if (textBody.trim()) {
        inboundTexts.push(textBody.trim());
        const cleaned = textBody.trim();
        if (isAdsPrefillGreeting(cleaned)) return;
        if (isKeyboardSmash(cleaned)) {
          smashTextsCount++;
          return;
        }
        if (GREETING_ONLY.test(cleaned)) {
          shortTextsCount++;
          return;
        }
        if (cleaned.length <= 5) {
          shortTextsCount++;
        } else {
          nonSpamTextsCount++;
        }
      }
    });

    const hasInsults = inboundTexts.some((text) =>
      COLOMBIAN_INSULTS.some((regex) => regex.test(text))
    );

    const allAudiosNonVerbal =
      audiosCount >= 1 &&
      audioClassifications.every((c) => c.kind === "non_verbal" || c.kind === "empty");
    const isPocketDialAudios = audiosCount >= 2 && allAudiosNonVerbal;

    const isMediaFloodChildPlay =
      audiosCount >= 2 && (imagesCount >= 2 || stickersCount >= 3);
    const isStickerFlood = stickersCount >= 4 && nonSpamTextsCount === 0 && !anyNonPrefillSignal;

    // Gibberish: ≥2 saludos/textos vacíos Y sin habla real Y sin otro contenido útil
    const isGibberishText =
      shortTextsCount >= 2 &&
      nonSpamTextsCount === 0 &&
      smashTextsCount === 0 &&
      !hasRealSpeech &&
      imagesCount === 0 &&
      (audiosCount === 0 || allAudiosNonVerbal);

    const isSmashText =
      smashTextsCount >= 1 && nonSpamTextsCount === 0 && !hasGenuineKeyword && !hasRealSpeech;
    const isBlacklisted = waId && BLACKLIST.includes(waId);

    // Prefill Meta solo (o prefill + stickers/ruido sin pedido real)
    isPrefillOnly =
      prefillOnlyTexts >= 1 &&
      nonPrefillTextCount === 0 &&
      !hasGenuineKeyword &&
      !hasRealSpeech &&
      audiosCount === 0 &&
      imagesCount === 0 &&
      smashTextsCount === 0;

    if (isBlacklisted) {
      isSpam = true;
      spamReason = "Phone number is blacklisted.";
    } else if (hasInsults) {
      isSpam = true;
      spamReason = "Insults / profanity detected.";
    } else if (isMediaFloodChildPlay) {
      isSpam = true;
      spamReason = `Child play / media flood detected (${audiosCount} audios and either ${imagesCount} images or ${stickersCount} stickers).`;
    } else if (isPocketDialAudios) {
      isSpam = true;
      spamReason = `Pocket dial detected (${audiosCount} audios with only background noise/silence).`;
    } else if (isStickerFlood) {
      isSpam = true;
      spamReason = `Sticker flood detected (${stickersCount} stickers).`;
    } else if (isSmashText) {
      isSpam = true;
      spamReason = "Keyboard smash / gibberish long text detected.";
    } else if (isGibberishText) {
      isSpam = true;
      spamReason = `Gibberish text detected (${shortTextsCount} short meaningless messages, no real speech).`;
    }
  }

  // Prefill-only también cuando hay genuine path corto-circuitado: recalcular bandera
  if (!hasHumanAssignee && !hasGenuineKeyword && !hasRealSpeech && !isSpam) {
    const onlyPrefill =
      inboundMessages.length > 0 &&
      inboundMessages.every((m) => {
        const type = String(m.message_type || m.type || "").toLowerCase();
        if (type === "audio" || type === "image" || type === "video" || type === "sticker" || type === "document") {
          return false;
        }
        const text = getMessageText(m);
        return !text || isAdsPrefillGreeting(text);
      });
    if (onlyPrefill) isPrefillOnly = true;
  }

  let spamProfile = null;
  if (isSpam) {
    spamProfile = {
      is_spam: true,
      reason: spamReason,
      classified_at: now,
    };
  } else if (isPrefillOnly) {
    spamProfile = {
      is_spam: false,
      ads_prefill_only: true,
      reason: "Meta Ads prefill greeting only — waiting for real message",
      classified_at: now,
    };
  } else if (vars.spam_profile?.is_spam) {
    spamProfile = {
      is_spam: false,
      reason: "Lead cured via real speech transcript, sports keyword, or staff override",
      classified_at: now,
    };
  } else {
    spamProfile = vars.spam_profile || null;
    if (spamProfile && spamProfile.ads_prefill_only && !isPrefillOnly) {
      spamProfile = {
        ...spamProfile,
        ads_prefill_only: false,
        reason: "Customer sent follow-up after ads prefill",
        classified_at: now,
      };
    }
  }

  const reason = String(
    system?.last_resume?.reason ||
      vars?.system?.last_resume?.reason ||
      executionContext?.last_resume?.reason ||
      body?.last_resume_reason ||
      ""
  ).toLowerCase();

  const shouldIgnore = isSpam || isPrefillOnly;

  let signal;
  let routeReason;
  if (reason === "user_input" && availableEdges.includes("user_input")) {
    signal = "user_input";
    routeReason = "burst_more_messages";
  } else if (shouldIgnore && availableEdges.includes("ignore")) {
    signal = "ignore";
    routeReason = isSpam ? `burst_ignore_spam:${spamReason}` : "burst_ignore_ads_prefill";
  } else if (availableEdges.includes("timeout")) {
    // Fallback: si no hay edge ignore, no mandar spam/prefill al vendedor si podemos
    // quedarnos en user_input; si no, timeout (el prompt del agente también silencia).
    if (shouldIgnore && availableEdges.includes("user_input") && reason !== "timeout") {
      signal = "user_input";
      routeReason = "burst_ignore_fallback_rewait";
    } else {
      signal = "timeout";
      routeReason = reason === "timeout" ? "burst_silence_timeout" : "burst_default_to_vendor";
    }
  } else if (availableEdges.includes("user_input")) {
    signal = "user_input";
    routeReason = "burst_fallback_input";
  } else {
    signal = availableEdges[0];
    routeReason = "first_edge";
  }

  return new Response(
    JSON.stringify({
      next_edge: signal,
      vars: {
        spam_profile: spamProfile,
        service: {
          ...(vars.service || {}),
          last_call_name: "route_customer_burst_resume",
          last_call_status: "ready",
          last_call_at: now,
          burst_resume_reason: reason || null,
          route_reason: routeReason,
        },
      },
    }),
    { headers: { "Content-Type": "application/json" } }
  );
}

// ===== route-customer-entry (189befcd-5a62-482a-ad95-982c6721ad3e) =====
/**
 * route_customer_entry — dual mode:
 * 1) Sales-gate (edges sales_allowed / send_message / already_notified):
 *    whitelist Diego → ventas; resto → mantenimiento.
 * 2) Normal: existing_customer (historial) vs new_customer (vendedor).
 *
 * Nota: Kapso no redeploya route-customer-paused; el decide de pausa usa este ID.
 */
async function handler(request, env) {
  const body = await request.json().catch(() => ({}));
  const availableEdges = Array.isArray(body?.available_edges) ? body.available_edges : [];
  const executionContext = body?.execution_context || {};
  const vars = executionContext.vars || {};
  const context = executionContext.context || {};
  const whatsappContext = body?.whatsapp_context || {};
  const conversation = whatsappContext.conversation || {};
  const now = new Date().toISOString();

  const localDigits = (digits) => {
    const d = String(digits || "").replace(/\D/g, "");
    return d.length >= 10 ? d.slice(-10) : d;
  };

  // —— Mode A: mantenimiento + whitelist ventas ——
  if (
    availableEdges.includes("sales_allowed") ||
    availableEdges.includes("send_message") ||
    availableEdges.includes("already_notified")
  ) {
    const waId = String(
      context?.phone_number ||
        conversation.phone_number ||
        vars?.user?.wa_id ||
        vars?.context?.phone_number ||
        ""
    ).replace(/\D/g, "");

    const DEFAULT_TESTERS = ["3000000047", "3000000047"];
    const fromEnv = String(env.LIFE_SALES_TESTER_WHITELIST || "")
      .split(/[,;\s]+/)
      .map((x) => x.replace(/\D/g, ""))
      .filter(Boolean);
    const allowed = [...DEFAULT_TESTERS, ...fromEnv]
      .map(localDigits)
      .filter((d) => d.length === 10);
    const incoming = localDigits(waId);
    const salesAllowed = Boolean(incoming && allowed.includes(incoming));
    const alreadySent = vars?.kapso?.maintenance_message_sent === true;

    let signal;
    let reason;
    if (salesAllowed && availableEdges.includes("sales_allowed")) {
      signal = "sales_allowed";
      reason = "sales_tester_whitelist";
    } else if (alreadySent && availableEdges.includes("already_notified")) {
      signal = "already_notified";
      reason = "maintenance_already_sent";
    } else if (availableEdges.includes("send_message")) {
      signal = "send_message";
      reason = "maintenance_first_message";
    } else {
      signal = availableEdges[0];
      reason = "first_edge";
    }

    return new Response(
      JSON.stringify({
        next_edge: signal,
        vars: {
          user: {
            ...(vars.user || {}),
            wa_id: waId || vars?.user?.wa_id || null,
            sales_tester: salesAllowed,
          },
          kapso: {
            ...(vars.kapso || {}),
            customer_lane: salesAllowed ? "sales_tester" : "paused_maintenance",
            staff_only_mode: !salesAllowed,
            sales_whitelist_gate: true,
            sales_allowed: salesAllowed,
          },
          service: {
            last_call_name: "route_customer_entry",
            last_call_status: "ready",
            last_call_at: now,
            routed_edge: signal,
            route_reason: reason,
            fallback_message: salesAllowed
              ? "Tester ventas — carril cliente abierto"
              : alreadySent
                ? "Mantenimiento ya enviado; conversacion en espera"
                : "Primer mensaje de mantenimiento",
          },
        },
      }),
      { headers: { "Content-Type": "application/json" } }
    );
  }

  // —— Mode B: historial vs vendedor ——
  const segment = String(vars?.user?.contact_segment || "new_customer");
  const returningSale =
    vars?.customer_line === "returning_sale" ||
    vars?.quote?.quote_request_source === "client_returning_sale";

  const lastText = [
    vars?.intent?.raw_text,
    vars?.last_user_input,
    vars?.context?.agent_last_message,
    executionContext?.last_user_input,
    body?.last_user_input,
  ]
    .map((t) => String(t || ""))
    .join("\n");

  // Señales de venta nueva (corpus Kapso: "Hola, quiero cotizar…")
  // Ojo: usar prefijos (cotiz…) — `\bcotiz\b` NO matchea "cotizar".
  const looksLikeNewQuote =
    /\b(cotiz\w*|precio|cu[aá]nto\s+sale|cu[aá]nto\s+cuesta|valor|abono)\b/i.test(lastText) ||
    /\b(quiero|necesito|necesitar[ií]amos)\b[\s\S]{0,40}\b(uniforme|camiseta|sudadera|peto|kit)s?\b/i.test(
      lastText
    ) ||
    /\b(uniforme|camiseta|sudadera)s?\b[\s\S]{0,40}\b(\d{1,3}|dry|dumonti|manga|cuello)\b/i.test(
      lastText
    ) ||
    /\.(xlsx|xlsm)|formato\s+pedido|image attached|document attached/i.test(lastText);

  // Solo seguimiento de pedido — no "Hola" ni msgs cortos de clientes conocidos
  const looksLikeHistoryOnly =
    !looksLikeNewQuote &&
    /\b(mi pedido|estado\s+(de\s+)?(mi\s+)?pedido|etapa|tarjeta|producci[oó]n|dise[nñ]o anterior|historial|seguimiento|d[oó]nde va|donde va|ya lo ped[ií]|n[uú]mero de pedido|pedido\s+S0\d+|S0\d{4,})\b/i.test(
      lastText
    );

  let signal;
  let reason;
  if (looksLikeNewQuote && availableEdges.includes("new_customer")) {
    signal = "new_customer";
    reason = "quote_intent";
  } else if (returningSale && availableEdges.includes("new_customer")) {
    signal = "new_customer";
    reason = "returning_sale_flag";
  } else if (
    looksLikeHistoryOnly &&
    availableEdges.includes("existing_customer")
  ) {
    signal = "existing_customer";
    reason = "history_intent";
  } else if (availableEdges.includes("new_customer")) {
    // Default: vendedor (también partners conocidos con "Hola" / msgs cortos)
    signal = "new_customer";
    reason = segment === "existing_customer" ? "existing_to_sales" : "new_or_fallback";
  } else if (availableEdges.includes("existing_customer")) {
    signal = "existing_customer";
    reason = "history_only_edge";
  } else {
    signal = availableEdges[0];
    reason = "first_edge";
  }

  const hasGreetingInText = /^(hola|buenas|buenos\s*dias|buen\s*dia|buenas\s*tardes|saludos)/i.test(lastText.trim());
  const isNewQuoteSession = !vars?.service?.greeting_sent || (hasGreetingInText && looksLikeNewQuote);

  return new Response(
    JSON.stringify({
      next_edge: signal,
      vars: {
        customer_line:
          signal === "new_customer"
            ? returningSale || looksLikeNewQuote
              ? "returning_sale"
              : "new_customer"
            : signal,
        quote:
          looksLikeNewQuote || returningSale
            ? (isNewQuoteSession
                ? {
                    quote_request_source:
                      segment === "existing_customer"
                        ? "client_returning_sale"
                        : "client_new",
                  }
                : {
                    ...(vars.quote || {}),
                    quote_request_source:
                      vars?.quote?.quote_request_source ||
                      (segment === "existing_customer"
                        ? "client_returning_sale"
                        : "client_new"),
                  })
            : vars.quote,
        service: {
          last_call_name: "route_customer_entry",
          last_call_status: "ready",
          last_call_at: now,
          routed_signal: segment,
          routed_edge: signal,
          route_reason: reason,
          returning_sale: Boolean(returningSale || looksLikeNewQuote),
          fallback_message: null,
          greeting_sent: isNewQuoteSession ? false : (vars.service?.greeting_sent ?? false),
        },
      },
    }),
    { headers: { "Content-Type": "application/json" } }
  );
}

