const PEDIDO_HEADERS = PEDIDO_ATTR_HEADERS;
const ensureFormularioHeaders = (snapshot) => {
  const sheet = findSheet(snapshot, /formulario|aprobaci/i);
  if (!sheet) return snapshot;
  for (const [col, label] of Object.entries(FORMULARIO_HEADERS)) {
    setHeaderIfNeeded(sheet, `${col}1`, label);
  }
  return snapshot;
};


/**
 * sync_order_draft_from_odoo — Kapso ← Odoo (fuente de verdad).
 * Reconstruye resolved_lines + people desde sale.order + spreadsheet.
 */
async function odooRpc(env, service, method, args) {
  const resp = await fetch(`${env.ODOO_URL}/jsonrpc`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      jsonrpc: "2.0",
      method: "call",
      params: { service, method, args },
    }),
  });
  const json = await resp.json();
  if (json?.error) throw new Error(json.error?.message || "Odoo RPC error");
  return json.result;
}

function decodeSnapshot(b64) {
  if (!b64 || b64 === false) return null;
  try {
    const binary = atob(String(b64));
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return JSON.parse(new TextDecoder().decode(bytes));
  } catch {
    try {
      // Node fallback
      const raw = Buffer.from(b64, "base64").toString("utf8");
      return JSON.parse(raw);
    } catch {
      return null;
    }
  }
}

async function syncOrderDraftFromOdoo(env, { orderId, orderName } = {}) {
  if (!env?.ODOO_URL || !env?.ODOO_DB || !env?.ODOO_USERNAME || !env?.ODOO_PASSWORD) {
    return { ok: false, error: "odoo_unavailable" };
  }
  const uid = await odooRpc(env, "common", "authenticate", [
    env.ODOO_DB,
    env.ODOO_USERNAME,
    env.ODOO_PASSWORD,
    {},
  ]);
  if (!uid) return { ok: false, error: "auth_failed" };

  const executeKw = (model, method, positionalArgs = [], kw = {}) =>
    odooRpc(env, "object", "execute_kw", [
      env.ODOO_DB,
      uid,
      env.ODOO_PASSWORD,
      model,
      method,
      positionalArgs,
      kw,
    ]);

  let soId = Number(orderId || 0) || null;
  if (!soId && orderName) {
    const found = await executeKw(
      "sale.order",
      "search_read",
      [[["name", "ilike", String(orderName).replace(/^S0*/i, "")]]],
      { fields: ["id", "name"], limit: 5 }
    );
    const exact = (found || []).find(
      (o) => String(o.name).toUpperCase() === String(orderName).toUpperCase()
    );
    soId = exact?.id || found?.[0]?.id || null;
  }
  if (!soId) return { ok: false, error: "order_not_found" };

  const orders = await executeKw(
    "sale.order",
    "read",
    [[soId]],
    {
      fields: [
        "id",
        "name",
        "state",
        "note",
        "partner_id",
        "order_line",
        "client_order_ref",
        "spreadsheet_ids",
      ],
    }
  );
  const order = orders?.[0];
  if (!order) return { ok: false, error: "order_not_found" };

  const lines = await executeKw(
    "sale.order.line",
    "search_read",
    [[["order_id", "=", soId], ["display_type", "=", false]]],
    {
      fields: [
        "id",
        "name",
        "product_id",
        "product_uom_qty",
        "price_unit",
        "product_template_id",
      ],
    }
  );

  const resolved_lines = [];
  for (let i = 0; i < (lines || []).length; i++) {
    const line = lines[i];
    const productId = line.product_id?.[0];
    if (!productId) continue;
    if (/dise[nñ]o/i.test(line.name || line.product_id?.[1] || "")) continue;

    let ptavs = [];
    const products = await executeKw(
      "product.product",
      "read",
      [[productId]],
      {
        fields: [
          "id",
          "display_name",
          "product_tmpl_id",
          "product_template_attribute_value_ids",
          "list_price",
        ],
      }
    );
    const product = products?.[0];
    if (product?.product_template_attribute_value_ids?.length) {
      ptavs = await executeKw(
        "product.template.attribute.value",
        "read",
        [product.product_template_attribute_value_ids],
        { fields: ["id", "name", "attribute_id"] }
      );
    }
    const split = splitProductDisplayName(product?.display_name || line.name);
    resolved_lines.push(
      buildResolvedLine(
        {
          line_id: `odoo_line_${line.id}`,
          product_text: product?.display_name || line.name,
          product_base: split.product_base,
          product_tmpl_id: product?.product_tmpl_id?.[0] || line.product_template_id?.[0],
          product_variant_id: productId,
          quantity: line.product_uom_qty,
          unit_cop: line.price_unit,
          confidence: "high",
          attributes: {
            ...split.embedded_attrs,
            ...attributesFromOdooPtavs(ptavs),
          },
        },
        i
      )
    );
  }

  let spreadsheetId = null;
  let spreadsheetUrl = null;
  let people = [];
  let pedidoAttrs = [];
  const sheetIds = order.spreadsheet_ids || [];
  if (sheetIds.length) {
    spreadsheetId = sheetIds[sheetIds.length - 1];
    const sheets = await executeKw(
      "sale.order.spreadsheet",
      "read",
      [[spreadsheetId]],
      { fields: ["id", "name", "spreadsheet_snapshot", "order_id"] }
    );
    const sheet = sheets?.[0];
    const snap = decodeSnapshot(sheet?.spreadsheet_snapshot);
    if (snap) {
      people = parsePeopleFromSpreadsheet(snap);
      pedidoAttrs = parsePedidoAttributes(snap);
      // merge pedido attrs into resolved lines by index
      pedidoAttrs.forEach((pa, idx) => {
        if (resolved_lines[idx]) {
          resolved_lines[idx].attributes = {
            ...resolved_lines[idx].attributes,
            ...pa.attributes,
          };
          if (pa.comments) resolved_lines[idx].comments = pa.comments;
          if (pa.product_base) resolved_lines[idx].product_base = pa.product_base;
        }
      });
    }
    spreadsheetUrl = `${env.ODOO_URL}/odoo/sales/${soId}/sale-order-spreadsheet/${spreadsheetId}`;
  }

  const detail = {
    schema_version: "life_order_people_v1",
    source: "odoo_sync",
    parse_status: "ok",
    people,
    person_count: people.length,
    rows: people.map((p) => ({
      nombre: p.identity?.print_name || "",
      numero: p.identity?.number || "",
      talla: p.components?.[0]?.size || "",
      comentario: p.comments || "",
      resolved_line_id: p.resolved_line_id || "",
    })),
  };

  return {
    ok: true,
    order: {
      id: order.id,
      name: order.name,
      state: order.state,
      partner_id: order.partner_id,
    },
    order_draft: {
      detail,
      commercial: {
        lines: resolved_lines.map((l) => ({
          product_text: l.product_text,
          quantity: l.quantity,
          category: l.category,
        })),
        resolved_lines,
      },
      spreadsheet: {
        id: spreadsheetId,
        url: spreadsheetUrl,
        status: people.length ? "complete" : "partial",
        source_of_truth: "odoo",
      },
      write: {
        status: "ready",
        code: "synced_from_odoo",
        synced_at: new Date().toISOString(),
      },
    },
  };
}



/**
 * Kapso tool: sync-order-draft-from-odoo
 */
function jsonResponse(payload, status = 200) {
  return new Response(JSON.stringify(payload), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

async function handler(request, env) {
  const body = await request.json().catch(() => ({}));
  const input = body?.input || {};
  const vars = body?.execution_context?.vars || {};
  const now = new Date().toISOString();

  if (vars?.user?.role !== "staff") {
    return jsonResponse({ ok: false, error: "staff_only" }, 403);
  }

  const orderId =
    Number(input.order_id || vars?.order?.id || vars?.order_correction?.target_order_id || 0) ||
    null;
  const orderName =
    input.order_name || vars?.order?.name || vars?.order_correction?.target_order_name || null;

  try {
    const result = await syncOrderDraftFromOdoo(env, { orderId, orderName });
    if (!result.ok) {
      return jsonResponse({
        ok: false,
        error: result.error,
        vars: {
          service: {
            last_call_name: "sync_order_draft_from_odoo",
            last_call_status: "error",
            last_call_at: now,
            fallback_message: `No pude sincronizar desde Odoo (${result.error}).`,
          },
        },
      });
    }
    return jsonResponse({
      ok: true,
      message: `Borrador actualizado desde Odoo ${result.order.name} (fuente de verdad).`,
      vars: {
        order: {
          id: result.order.id,
          name: result.order.name,
          status: result.order.state,
        },
        order_draft: result.order_draft,
        fidelity: mergeFidelityAfterSync(vars.fidelity, result.order_draft, now),
        service: {
          last_call_name: "sync_order_draft_from_odoo",
          last_call_status: "ready",
          last_call_at: now,
          fallback_message: null,
        },
      },
    });
  } catch (error) {
    return jsonResponse({
      ok: false,
      error: String(error?.message || error),
      vars: {
        service: {
          last_call_name: "sync_order_draft_from_odoo",
          last_call_status: "error",
          last_call_at: now,
          fallback_message: "Fallo al leer el pedido en Odoo.",
        },
      },
    });
  }
}


function num(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
}

function normalizeLine(line = {}) {
  return {
    product_variant_id: num(line.product_variant_id || line.odoo_product_id || line.product_id),
    product_text: compact(line.product_text || line.product_base || line.name).toLowerCase(),
    quantity: num(line.quantity),
    attributes: {
      cuello: compact(line.attributes?.cuello || line.collar).toLowerCase(),
      manga: compact(line.attributes?.manga || line.sleeves).toLowerCase(),
      tela: compact(line.attributes?.tela || line.material).toLowerCase(),
    },
  };
}

function lineKey(line) {
  if (line.product_variant_id) return `id:${line.product_variant_id}`;
  return `t:${line.product_text}|${line.attributes.cuello}|${line.attributes.manga}|${line.attributes.tela}`;
}

function mergeFidelityAfterSync(prevFidelity, orderDraft, now) {
  const fidelity = { ...(prevFidelity || {}) };
  const snapshot = fidelity.kapso_snapshot;
  if (!snapshot) return fidelity;

  const kapsoLines = (snapshot.resolved_lines || []).map(normalizeLine).filter((l) => l.quantity > 0);
  const current =
    orderDraft?.commercial?.resolved_lines || orderDraft?.commercial?.lines || [];
  const currentLines = (Array.isArray(current) ? current : [])
    .map(normalizeLine)
    .filter((l) => l.quantity > 0);

  if (!kapsoLines.length) {
    return {
      ...fidelity,
      pass_clean: false,
      retention_pct: null,
      last_compared_at: now,
      last_compare_source: "sync_order_draft_from_odoo",
    };
  }

  const byKey = new Map(currentLines.map((l) => [lineKey(l), l]));
  let matched = 0;
  let total = 0;
  let linesChanged = 0;
  for (const k of kapsoLines) {
    const c = byKey.get(lineKey(k));
    total += 3;
    if (!c) {
      linesChanged += 1;
      continue;
    }
    if (k.quantity === c.quantity) matched += 1;
    else linesChanged += 1;
    if (!k.product_variant_id || k.product_variant_id === c.product_variant_id) matched += 1;
    else linesChanged += 1;
    if (!k.product_text || k.product_text === c.product_text) matched += 1;
    else linesChanged += 1;
  }
  for (const c of currentLines) {
    if (!kapsoLines.some((k) => lineKey(k) === lineKey(c))) linesChanged += 1;
  }
  const retention_pct = total > 0 ? Math.round((1000 * matched) / total) / 10 : 0;
  return {
    ...fidelity,
    pass_clean: linesChanged === 0 && retention_pct >= 99.9,
    retention_pct,
    correction_burden: Math.round(10 * (100 - retention_pct)) / 10,
    lines_changed: linesChanged,
    last_compared_at: now,
    last_compare_source: "sync_order_draft_from_odoo",
  };
}

// ===== validate-nomina-confirm (d719ba6e-e2d2-45cf-a8e6-3339adaa9e0c) =====
async function handler(request, env) {
  const body = await request.json().catch(() => ({}));
  const vars = body?.execution_context?.vars || {};
  const now = new Date().toISOString();

  if (vars?.user?.role !== "staff") {
    return blocked("Solo staff autorizado puede registrar nómina.", now);
  }

  const confirmed = Boolean(vars?.nomina?.confirmed);
  const draft = vars?.nomina?.draft;
  const hasDraft = Boolean(draft?.employees?.length);
  const legacyManual =
    String(vars?.nomina?.employee_name || "").trim() &&
    String(vars?.nomina?.period || "").trim();

  if (!confirmed) {
    return blocked("Falta confirmacion (nomina.confirmed = true). Escriba CONFIRMO NOMINA.", now);
  }
  if (!hasDraft && !legacyManual) {
    return blocked("Falta borrador attlog o datos manuales de nomina.", now);
  }

  return ok(now, vars);
}

function ok(now, vars) {
  return new Response(
    JSON.stringify({
      vars: {
        staff: {
          ...(vars?.staff || {}),
          write_status: "ok",
          write_blocked_reason: null,
          registration_type: "nomina",
        },
        service: {
          last_call_name: "validate_nomina_confirm",
          last_call_status: "ready",
          last_call_at: now,
          fallback_message: null,
        },
      },
      status: "ready",
    }),
    { headers: { "Content-Type": "application/json" } }
  );
}

function blocked(message, now) {
  return new Response(
    JSON.stringify({
      vars: {
        staff: {
          write_status: "blocked",
          write_blocked_reason: message,
          registration_type: "nomina",
        },
        service: {
          last_call_name: "validate_nomina_confirm",
          last_call_status: "blocked",
          last_call_at: now,
          fallback_message: message,
        },
      },
      status: "blocked",
      message,
    }),
    { headers: { "Content-Type": "application/json" } }
  );
}

// ===== validate-staff-write (4061a9e7-fce9-4301-81e7-bd2e47da3da4) =====
/**
 * validate_staff_write — gate de confianza para carril staff.
 * ready → ok | needs_confirmation → needs_confirmation | blocked → blocked
 *
 * write_mode opportunity_only | sale_order (CRM-first jul 2026).
 * NOTE: evaluateStaffWriteReadiness alineada con lib/staff_order_contract.js.
 */
async function handler(request, env) {
  const body = await request.json().catch(() => ({}));
  const vars = body?.execution_context?.vars || {};
  const now = new Date().toISOString();

  const inboxSilent = vars?.staff?.upload_source === "inbox_silent";
  if (vars?.user?.role !== "staff" && !inboxSilent) {
    return blocked("Solo staff autorizado puede registrar pedidos.", now);
  }

  const writeMode = resolveWriteMode(vars);
  const readiness =
    writeMode === "opportunity_only"
      ? evaluateOpportunityReadiness(vars)
      : evaluateStaffWriteReadiness(vars);
  const orderDraft = vars.order_draft || {};

  if (readiness.status === "blocked") {
    return blocked(readiness.message || "Pedido incompleto.", now, readiness);
  }

  if (readiness.status === "needs_staff_confirmation") {
    return needsConfirmation(readiness, now, orderDraft);
  }

  const cross = readiness.cross_check;
  const needsReconcile = cross && !cross.ok;
  return ok(now, readiness, orderDraft, needsReconcile, writeMode);
}

function resolveWriteMode(vars = {}) {
  // Presupuesto intent gana sobre mode CRM stale (opportunity_only en order_draft.write).
  if (hasHazPresupuesto(vars) || hasConfirmoPresupuesto(vars)) return "sale_order";
  const staffMode = String(vars?.staff?.write_mode || "")
    .trim()
    .toLowerCase();
  if (staffMode === "sale_order") return "sale_order";
  if (staffMode === "opportunity_only") return "opportunity_only";
  const draftMode = String(vars?.order_draft?.write?.mode || "")
    .trim()
    .toLowerCase();
  if (draftMode === "sale_order") return "sale_order";
  if (vars?.user?.role === "staff") return "opportunity_only";
  return "sale_order";
}

function evaluateOpportunityReadiness(vars = {}) {
  const orderDraft = vars.order_draft || {};
  const quote = vars.quote || {};
  const customer =
    compact(quote.customer_display_name) ||
    compact(quote.order_or_team_name_for_billing) ||
    compact(vars?.["quote.customer_display_name"]) ||
    compact(orderDraft?.customer_display_name);
  if (!customer || /^cliente life$/i.test(customer)) {
    return {
      status: "blocked",
      code: "no_customer",
      message: "Falta el nombre del cliente para crear la oportunidad CRM.",
      fingerprint: null,
      resolved_lines: [],
      cross_check: null,
      write_mode: "opportunity_only",
    };
  }

  let resolved = Array.isArray(orderDraft.commercial?.resolved_lines)
    ? orderDraft.commercial.resolved_lines.map((l, i) => buildResolvedLine(l, i))
    : [];
  if (!resolved.length && Array.isArray(orderDraft.commercial?.lines)) {
    resolved = orderDraft.commercial.lines.map((l, i) => buildResolvedLine(l, i));
  }
  if (!resolved.length && String(quote.product_text || "").trim()) {
    resolved = [
      buildResolvedLine(
        {
          product_text: quote.product_text,
          quantity: quote.quantity,
          product_variant_id: quote.odoo_product_id,
          confidence: quote.match_confidence || "medium",
          attributes: quote.product_attributes,
          category: /uniforme/i.test(quote.product_text) ? "uniforme" : null,
        },
        0
      ),
    ];
  }
  if (!resolved.length) {
    return {
      status: "blocked",
      code: "no_lines",
      message: "Para la oportunidad hace falta un estimado (ej. 20 uniformes de futbol).",
      fingerprint: null,
      resolved_lines: [],
      cross_check: null,
      write_mode: "opportunity_only",
    };
  }

  const fingerprint = stableFingerprint({
    mode: "opportunity_only",
    customer,
    resolved_lines: resolved.map((l) => ({
      product_text: l.product_text,
      quantity: l.quantity,
    })),
  });

  return {
    status: "ready",
    code: "opportunity_ready",
    message: null,
    fingerprint,
    resolved_lines: resolved,
    cross_check: null,
    write_mode: "opportunity_only",
  };
}

function evaluateStaffWriteReadiness(vars = {}) {
  const orderDraft = vars.order_draft || {};
  const quote = vars.quote || {};
  const staff = vars.staff || {};

  let resolved = Array.isArray(orderDraft.commercial?.resolved_lines)
    ? orderDraft.commercial.resolved_lines.map((l, i) => buildResolvedLine(l, i))
    : [];

  if (!resolved.length && Array.isArray(orderDraft.commercial?.lines)) {
    resolved = orderDraft.commercial.lines.map((l, i) => buildResolvedLine(l, i));
  }

  if (!resolved.length && String(quote.product_text || "").trim()) {
    resolved = [
      buildResolvedLine(
        {
          product_text: quote.product_text,
          quantity: quote.quantity,
          product_variant_id: quote.odoo_product_id,
          confidence: quote.match_confidence || "",
          attributes: quote.product_attributes,
          category: /uniforme/i.test(quote.product_text) ? "uniforme" : null,
        },
        0
      ),
    ];
  }

  if (!resolved.length) {
    return {
      status: "blocked",
      code: "no_lines",
      message: "Pedido incompleto: sin lineas comerciales.",
      fingerprint: null,
      resolved_lines: [],
      cross_check: null,
    };
  }

  const baseUniformQty = resolved
    .filter((l) => l.category === "uniforme" || /uniforme/i.test(l.product_text || ""))
    .reduce((s, l) => s + Number(l.quantity || 0), 0);
  if (baseUniformQty > 0 && baseUniformQty < 6) {
    return {
      status: "blocked",
      code: "min_uniform",
      message: "Pedido incompleto: minimo 6 uniformes del mismo diseno.",
      fingerprint: null,
      resolved_lines: resolved,
      cross_check: null,
    };
  }

  if (baseUniformQty === 0) {
    const below = resolved.find((l) => Number(l.quantity || 0) < 6);
    if (below) {
      return {
        status: "blocked",
        code: "min_standalone",
        message: `Pedido minimo 6 unidades de ${below.product_base || below.product_text}.`,
        fingerprint: null,
        resolved_lines: resolved,
        cross_check: null,
      };
    }
  }

  const fingerprint = stableFingerprint({
    resolved_lines: resolved,
    detail: orderDraft.detail,
    partner_key:
      quote.customer_wa_id ||
      quote.customer_display_name ||
      quote.order_or_team_name_for_billing ||
      "",
  });

  const unresolved = resolved.filter((l) => !Number(l.product_variant_id || 0));
  const ambiguous = resolved.filter((l) =>
    ["low", "none", "medium"].includes(String(l.confidence || ""))
  );
  const parseStatus = String(orderDraft.detail?.parse_status || "");
  const hasBlockers = Boolean(orderDraft.blockers?.length);
  const hasDetailWarnings = Boolean(orderDraft.detail?.warnings?.length);
  const needsReviewStatus = parseStatus === "needs_review";
  // "partial" solo pide CONFIRMO si además hay ambigüedad comercial o warnings.
  // Listas FORMATO LIFE suelen marcar partial y aun así resolver high+variant.
  const hasWarnings = hasBlockers || hasDetailWarnings || needsReviewStatus;

  const confirmoText = hasHazPresupuesto(vars) || hasConfirmoPresupuesto(vars) || hasConfirmoSubir(vars);
  const confirmed =
    (String(staff.confirmation_fingerprint || "").trim() &&
      String(staff.confirmation_fingerprint).trim() === fingerprint) ||
    (confirmoText && Boolean(fingerprint));

  // Presupuesto requiere intent explícito (salvo fingerprint ya seteado).
  if (!confirmed && !hasHazPresupuesto(vars) && !hasConfirmoPresupuesto(vars) && !hasConfirmoSubir(vars)) {
    const peopleCount = Array.isArray(orderDraft.detail?.rows)
      ? orderDraft.detail.rows.length
      : Array.isArray(orderDraft.detail?.people)
        ? orderDraft.detail.people.length
        : 0;
    const hasRefs = Boolean(
      orderDraft.attachments?.length ||
        orderDraft.detail?.attachments?.length ||
        orderDraft.evidence?.length ||
        vars?.staff?.has_order_attachments
    );
    if (peopleCount < 1 || !hasRefs) {
      return {
        status: "blocked",
        code: "presupuesto_incomplete",
        message:
          "Para presupuesto hace falta lista completa y referencias/adjuntos. Sigue refinando la oportunidad CRM; cuando esté listo escribe HAZ PRESUPUESTO.",
        fingerprint,
        resolved_lines: resolved,
        cross_check: null,
        write_mode: "sale_order",
      };
    }
    return {
      status: "needs_staff_confirmation",
      code: "needs_presupuesto_intent",
      message:
        "Lista y referencias listas. Responde HAZ PRESUPUESTO para crear el borrador SO ligado a la oportunidad.",
      fingerprint,
      resolved_lines: resolved,
      cross_check: null,
      write_mode: "sale_order",
    };
  }

  // Solo pedir confirmación extra si hubo match ambiguo, warnings, o variantes parciales
  const compiledAmbiguity =
    ambiguous.length > 0 ||
    (unresolved.length > 0 &&
      resolved.some((l) => String(l.confidence || "") === "high"));

  const allResolvedHigh =
    resolved.length > 0 &&
    unresolved.length === 0 &&
    resolved.every((l) => String(l.confidence || "") === "high");

  if ((compiledAmbiguity || hasWarnings || (parseStatus === "partial" && !allResolvedHigh)) && !confirmed) {
    const summary = resolved
      .map(
        (l) =>
          `• ${l.product_base || l.product_text} × ${l.quantity}` +
          (l.product_variant_id ? "" : " (sin variante)") +
          (l.confidence && l.confidence !== "high" ? ` [${l.confidence}]` : "")
      )
      .join("\n");
    return {
      status: "needs_staff_confirmation",
      code: "needs_confirmation",
      message: `Hay ambiguedad o parseo parcial. Resumen:\n${summary}\nResponde HAZ PRESUPUESTO (o CONFIRMO PRESUPUESTO) para crear el borrador.`,
      fingerprint,
      resolved_lines: resolved,
      cross_check: null,
      write_mode: "sale_order",
    };
  }

  if (confirmed && unresolved.length) {
    return {
      status: "blocked",
      code: "unresolved_variant",
      message: `Falta variante Odoo exacta para: ${unresolved.map((l) => l.product_text).join(", ")}`,
      fingerprint,
      resolved_lines: resolved,
      cross_check: null,
    };
  }
  const cross = crossCheckPeopleVsLines({
    detail: orderDraft.detail,
    resolvedLines: resolved,
  });

  return {
    status: "ready",
    code: "pedido_ready",
    message: null,
    fingerprint,
    resolved_lines: resolved,
    cross_check: cross,
  };
}

function compact(value) {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

/** CONFIRMO SUBIR — legacy; preferir HAZ PRESUPUESTO. */
function hasConfirmoSubir(vars = {}) {
  return staffReplyMatches(vars, /\bCONFIRMO\s+SUBIR\b/i);
}

function hasHazPresupuesto(vars = {}) {
  // Acepta "HAZ PRESUPUESTO", "has el presupuesto", "crear el presupuesto borrador".
  return staffReplyMatches(
    vars,
    /\b(HAZ|HAS|HACE|CREA|CREAR)(?:\s+\w+){0,3}\s+PRESUPUESTO\b/i
  );
}

function hasConfirmoPresupuesto(vars = {}) {
  return staffReplyMatches(vars, /\bCONFIRMO\s+PRESUPUESTO\b/i);
}

function staffReplyMatches(vars = {}, re) {
  const staff = vars.staff || {};
  const context = vars.context || {};
  const intent = vars.intent || {};
  const chunks = [
    vars.staff_lane_reply,
    staff.lane_reply,
    staff.last_user_text,
    staff.last_inbound_text,
    context.last_user_text,
    context.last_inbound_text,
    intent.raw_text,
    intent.text,
    vars.last_user_input,
    vars.last_user_text,
    vars.last_inbound_text,
    vars.message,
    vars.body,
  ];
  return chunks.some((t) => re.test(String(t || "")));
}

function splitProductDisplayName(displayName) {
  const raw = compact(displayName);
  if (!raw) return { product_base: "", embedded_attrs: {} };
  const m = raw.match(/^(.+?)\s*\((.+)\)\s*$/);
  if (!m) return { product_base: raw, embedded_attrs: {} };
  return { product_base: compact(m[1]), embedded_attrs: {} };
}

function buildResolvedLine(input = {}, index = 0) {
  const productText = compact(input.product_text || input.name || "");
  const split = splitProductDisplayName(input.display_name || productText);
  const qty = Math.max(0, Number(input.quantity || input.product_uom_qty || 0));
  const confidence = compact(input.confidence || input.match_confidence || "");
  return {
    line_id:
      compact(input.line_id) ||
      `rl_${index + 1}_${String(input.product_variant_id || input.odoo_product_id || productText)
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "_")
        .slice(0, 40)}`,
    product_text: productText || split.product_base,
    product_base: compact(input.product_base) || split.product_base || productText,
    product_tmpl_id: Number(input.product_tmpl_id || 0) || null,
    product_variant_id:
      Number(input.product_variant_id || input.odoo_product_id || input.product_id || 0) || null,
    attributes: input.attributes || input.product_attributes || {},
    quantity: qty,
    unit_cop: Number(input.unit_cop || input.unit_price || 0) || null,
    confidence,
    category: compact(input.category || "").toLowerCase() || null,
    comments: compact(input.comments || input.variant_notes || ""),
  };
}

function peopleForSpreadsheet(detail = {}) {
  if (Array.isArray(detail.people) && detail.people.length) {
    return detail.people.map((person, i) => {
      const identity = person.identity || {};
      const primary = (person.components || [])[0] || {};
      return {
        person_id: person.person_id || `p${i + 1}`,
        nombre: compact(identity.print_name || identity.display_name || ""),
        numero: compact(identity.number || ""),
        talla: compact(primary.size || ""),
        resolved_line_id: compact(primary.resolved_line_id || person.resolved_line_id || ""),
        product_line_key: compact(primary.product_line_key || person.product_line_key || ""),
      };
    });
  }
  return (detail.rows || []).map((row, i) => ({
    person_id: `r${i + 1}`,
    nombre: compact(row.nombre || ""),
    numero: compact(row.numero || ""),
    talla: compact(row.talla || ""),
    resolved_line_id: compact(row.resolved_line_id || ""),
    product_line_key: compact(row.product_line_key || ""),
  }));
}

function crossCheckPeopleVsLines({ detail = {}, resolvedLines = [] } = {}) {
  const people = peopleForSpreadsheet(detail);
  const productLines = (resolvedLines || []).filter(
    (line) =>
      Number(line.quantity || 0) > 0 &&
      !/dise[nñ]o/i.test(line.product_base || line.product_text || "")
  );
  const totalQty = productLines.reduce((s, l) => s + Number(l.quantity || 0), 0);
  const personCount = people.length;
  const mismatches = [];
  if (productLines.length && personCount && personCount !== totalQty) {
    mismatches.push({
      code: "qty_people_vs_lines",
      message: `Personas (${personCount}) != lineas (${totalQty})`,
    });
  }
  return {
    status: mismatches.length ? "mismatch" : personCount || totalQty ? "complete" : "empty",
    ok: mismatches.length === 0,
    person_count: personCount,
    line_qty: totalQty,
    mismatches,
  };
}

function stableFingerprint(payload = {}) {
  const lines = (payload.resolved_lines || [])
    .map((l) => ({
      p: Number(l.product_variant_id || 0) || String(l.product_text || ""),
      q: Number(l.quantity || 0),
    }))
    .sort((a, b) => String(a.p).localeCompare(String(b.p)));
  const people = peopleForSpreadsheet(payload.detail || {})
    .map((p) => `${p.numero}|${p.nombre}|${p.talla}`)
    .sort();
  return JSON.stringify({ lines, people, partner: String(payload.partner_key || "") });
}

function ok(now, readiness, orderDraft, needsReconcile, writeMode = "sale_order") {
  return new Response(
    JSON.stringify({
      vars: {
        staff: {
          write_status: "ok",
          write_code: readiness.code || "pedido_ready",
          write_blocked_reason: null,
          write_mode: writeMode || readiness.write_mode || "sale_order",
          registration_type: "pedido",
          confirmation_fingerprint: readiness.fingerprint || null,
        },
        order_draft: {
          ...orderDraft,
          commercial: {
            ...(orderDraft.commercial || {}),
            resolved_lines: readiness.resolved_lines,
          },
          write: {
            status: needsReconcile ? "needs_human_reconcile" : "ready",
            code: readiness.code,
            fingerprint: readiness.fingerprint,
            mode: writeMode || readiness.write_mode || "sale_order",
          },
          spreadsheet: {
            ...(orderDraft.spreadsheet || {}),
            status: readiness.cross_check?.status || orderDraft.spreadsheet?.status || "empty",
            cross_check: readiness.cross_check,
          },
        },
        service: {
          last_call_name: "validate_staff_write",
          last_call_status: "ready",
          last_call_at: now,
          routed_registration_type: "pedido",
          fallback_message: needsReconcile
            ? "SO se creara pero hay descuadre personas vs cantidades; revisar Formulario."
            : null,
        },
      },
      status: "ready",
    }),
    { headers: { "Content-Type": "application/json" } }
  );
}

function needsConfirmation(readiness, now, orderDraft) {
  return new Response(
    JSON.stringify({
      vars: {
        staff: {
          write_status: "needs_confirmation",
          write_code: readiness.code,
          write_blocked_reason: readiness.message,
          registration_type: "pedido",
        },
        order_draft: {
          ...orderDraft,
          commercial: {
            ...(orderDraft.commercial || {}),
            resolved_lines: readiness.resolved_lines,
          },
          write: {
            status: "needs_staff_confirmation",
            code: readiness.code,
            fingerprint: readiness.fingerprint,
          },
        },
        service: {
          last_call_name: "validate_staff_write",
          last_call_status: "needs_confirmation",
          last_call_at: now,
          routed_registration_type: "pedido",
          fallback_message: readiness.message,
        },
      },
      status: "needs_confirmation",
      message: readiness.message,
    }),
    { headers: { "Content-Type": "application/json" } }
  );
}

function blocked(message, now, readiness = null) {
  return new Response(
    JSON.stringify({
      vars: {
        staff: {
          write_status: "blocked",
          write_code: readiness?.code || "blocked",
          write_blocked_reason: message,
          registration_type: "pedido",
        },
        order_draft: readiness
          ? {
              write: {
                status: "blocked",
                code: readiness.code,
                fingerprint: readiness.fingerprint,
              },
              commercial: {
                resolved_lines: readiness.resolved_lines || [],
              },
            }
          : undefined,
        service: {
          last_call_name: "validate_staff_write",
          last_call_status: "blocked",
          last_call_at: now,
          routed_registration_type: "pedido",
          fallback_message: message,
        },
      },
      status: "blocked",
      message,
    }),
    { headers: { "Content-Type": "application/json" } }
  );
}
